BEGIN
  PERFORM new_design.add_registered_dependency(
    'card_version',NEW.card_id,NEW.card_version_id,
    'planning_version',NEW.planning_object_id,NEW.planning_version_id,
    'planned_from','hard','manual',NEW.planning_version_id
  );
