--
-- Name: bridge_publication_export_to_outbox(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.bridge_publication_export_to_outbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE queued_job uuid; book_space uuid;
BEGIN
  SELECT space_id INTO book_space FROM books WHERE id=NEW.book_id;
  queued_job:=enqueue_registered_background_job('publication_export_request',NEW.id,book_space,NEW.book_id,NULL,NULL);
  UPDATE publication_export_requests SET job_id=queued_job WHERE id=NEW.id;
  RETURN NEW;
END $$;


--
-- Name: bridge_specialized_request_to_outbox(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.bridge_specialized_request_to_outbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE request_kind text; request_book uuid; request_space uuid; correlation uuid; causation uuid;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'dependency_recompute_requests' THEN request_kind:='dependency_recompute_request'; request_book:=NEW.book_id; correlation:=NEW.invalidation_event_id; causation:=NEW.target_resource_id;
    WHEN 'asset_derivations' THEN request_kind:='asset_derivation'; request_book:=NEW.book_id; causation:=NEW.source_asset_version_id;
    WHEN 'graph_projection_requests' THEN request_kind:='graph_projection_request'; request_book:=NEW.book_id; correlation:=NEW.generation_id; causation:=NEW.dependency_resource_id;
    WHEN 'chunking_requests' THEN request_kind:='embedding_chunking_request'; request_book:=NEW.book_id; causation:=NEW.source_snapshot_id;
    WHEN 'embedding_requests' THEN request_kind:='embedding_request'; request_book:=NEW.book_id; causation:=NEW.chunk_id;
    WHEN 'embedding_index_generations' THEN request_kind:='embedding_index_generation'; request_book:=NEW.book_id; causation:=NEW.profile_version_id;
    WHEN 'ai_tasks' THEN request_kind:='ai_task'; request_book:=NEW.book_id; request_space:=NEW.space_id; causation:=NEW.source_id;
  END CASE;
  IF request_space IS NULL THEN SELECT space_id INTO request_space FROM books WHERE id=request_book; END IF;
  PERFORM enqueue_registered_background_job(request_kind,NEW.id,request_space,request_book,correlation,causation);
  RETURN NEW;
END $$;


--
-- Name: bridge_transfer_operation_to_outbox(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.bridge_transfer_operation_to_outbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  PERFORM enqueue_registered_background_job('backup_request',NEW.id,NEW.space_id,NEW.book_id,NULL,NULL);
  RETURN NEW;
END $$;


--
-- Name: build_embedding_generation_index(uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.build_embedding_generation_index(requested_generation_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $_$
DECLARE row_data embedding_index_generations%ROWTYPE; dims integer; metric text; opclass text; sql_text text;
BEGIN
  SELECT * INTO row_data FROM embedding_index_generations WHERE id=requested_generation_id FOR UPDATE;
  IF row_data.status NOT IN ('building','verifying') OR row_data.index_name !~ '^nd_hnsw_[a-f0-9]{32}$' THEN RAISE EXCEPTION 'generation is not buildable' USING ERRCODE='23514'; END IF;
  SELECT dimensions,distance_metric INTO dims,metric FROM embedding_profile_versions WHERE id=row_data.profile_version_id;
  opclass:=CASE metric WHEN 'cosine' THEN 'vector_cosine_ops' WHEN 'l2' THEN 'vector_l2_ops' WHEN 'inner_product' THEN 'vector_ip_ops' ELSE NULL END;
  IF opclass IS NULL THEN RAISE EXCEPTION 'unsupported vector metric' USING ERRCODE='23514'; END IF;
  sql_text:=format('CREATE INDEX %I ON new_design.embedding_vectors USING hnsw ((embedding::vector(%s)) %s) WHERE generation_id=%L::uuid AND status=''eligible''',row_data.index_name,dims,opclass,row_data.id::text);
  EXECUTE sql_text;
  UPDATE embedding_index_generations SET status='verifying' WHERE id=requested_generation_id;
END $_$;


--
-- Name: cascade_embedding_profile_archive(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.cascade_embedding_profile_archive() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF OLD.status='active' AND NEW.status='archived' THEN
    UPDATE embedding_source_snapshots source SET status='stale',stale_at=now() WHERE source.status='current' AND source.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_chunks chunk SET status='stale',stale_at=now() WHERE chunk.status='current' AND chunk.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_vectors item SET status='stale' WHERE item.status='eligible' AND item.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_requests request SET status='stale',updated_at=now() WHERE request.status IN ('pending','running','retry_scheduled','succeeded') AND request.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_index_generations generation SET status='stale' WHERE generation.status IN ('ready','active') AND generation.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_index_states SET status='stale',revision=revision+1,updated_at=now() WHERE profile_id=NEW.id;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_world_package_complete_refs(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.check_world_package_complete_refs() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $$
BEGIN
 IF TG_TABLE_NAME='world_package_versions' THEN
  IF (SELECT count(*) FROM world_package_card_refs WHERE package_id=NEW.id)<>jsonb_array_length(NEW.frame->'cards') OR (SELECT count(*) FROM world_package_relation_refs WHERE package_id=NEW.id)<>jsonb_array_length(NEW.frame->'relations') THEN RAISE EXCEPTION 'incomplete frozen world reference set' USING ERRCODE='23514'; END IF;
 ELSE
  IF (SELECT count(*) FROM world_package_install_card_refs WHERE installation_id=NEW.id)<>jsonb_array_length(NEW.receipt->'cards') OR (SELECT count(*) FROM world_package_install_relation_refs WHERE installation_id=NEW.id)<>jsonb_array_length(NEW.receipt->'relations') THEN RAISE EXCEPTION 'incomplete world installation mapping' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: check_world_sync_complete_children(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.check_world_sync_complete_children() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $$
DECLARE selected jsonb; fields integer; relations integer;
BEGIN
 selected:=world_sync_selected_input(NEW);
 IF NEW.operation='push' THEN
  IF (SELECT count(*) FROM world_package_push_candidates WHERE command_id=NEW.id)<>1 THEN RAISE EXCEPTION 'world push requires original candidate' USING ERRCODE='23514'; END IF;
 ELSIF NEW.operation IN ('pull','publish') THEN
  fields:=jsonb_array_length(selected->'choices')+coalesce((SELECT sum(jsonb_array_length(card->'mapping')) FROM jsonb_array_elements(coalesce(selected->'newCards','[]'::jsonb)) card),0);
  relations:=jsonb_array_length(coalesce(selected->'relationChoices','[]'::jsonb));
  IF selected IS NULL OR (SELECT count(*) FROM world_package_field_baselines WHERE command_id=NEW.id)<>fields
   OR (SELECT count(*) FROM world_package_relation_baselines WHERE command_id=NEW.id)<>relations
   OR (NEW.operation='pull' AND (SELECT count(*) FROM world_package_added_card_refs WHERE command_id=NEW.id)<>jsonb_array_length(coalesce(selected->'newCards','[]'::jsonb)))
  THEN RAISE EXCEPTION 'world sync requires complete selected mappings and baselines' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: context_activation_rule_stats(jsonb, integer); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.context_activation_rule_stats(node jsonb, depth integer DEFAULT 1) RETURNS TABLE(max_depth integer, condition_count integer, is_valid boolean)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE child jsonb; child_stats record; field_name text; operator_name text;
BEGIN
  IF jsonb_typeof(node)<>'object' OR depth>4 THEN RETURN QUERY SELECT depth,0,false; RETURN; END IF;
  IF node->>'kind'='condition' THEN
    field_name:=node->>'field'; operator_name:=node->>'operator';
    RETURN QUERY SELECT depth,1,
      field_name=ANY(ARRAY['task_key','task_group','content_type','tag','material_status','canonical_status','volume','chapter','scene','story_range','relation_exists','association_exists','source_type','stale','manual_switch'])
      AND operator_name=ANY(ARRAY['equals','not_equals','in','not_in','contains','exists','not_exists','gte','lte','between','enabled'])
      AND (node-ARRAY['kind','field','operator','value']::text[])='{}'::jsonb
      AND (NOT (node ? 'value') OR jsonb_typeof(node->'value') IN ('string','number','boolean','array','null'))
      AND (NOT (node ? 'value') OR jsonb_typeof(node->'value')<>'array' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(node->'value') AS array_item(value) WHERE jsonb_typeof(value) NOT IN ('string','number')));
    RETURN;
  END IF;
  IF node->>'kind'<>'group' OR NOT (node->>'operator'=ANY(ARRAY['and','or'])) OR (node-ARRAY['kind','operator','items']::text[])<>'{}'::jsonb OR jsonb_typeof(node->'items')<>'array' OR jsonb_array_length(node->'items')>20 THEN
    RETURN QUERY SELECT depth,0,false; RETURN;
  END IF;
  max_depth:=depth; condition_count:=0; is_valid:=true;
  FOR child IN SELECT value FROM jsonb_array_elements(node->'items') LOOP
    SELECT * INTO child_stats FROM context_activation_rule_stats(child,depth+1);
    max_depth:=greatest(max_depth,child_stats.max_depth); condition_count:=condition_count+child_stats.condition_count; is_valid:=is_valid AND child_stats.is_valid;
  END LOOP;
  is_valid:=is_valid AND condition_count<=40;
  RETURN NEXT;
END $$;


--
-- Name: create_character_author_influence_candidate(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.create_character_author_influence_candidate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'new_design', 'public', 'pg_temp'
    AS $$
DECLARE first_order integer;
BEGIN
 IF NEW.status='succeeded' AND NEW.output->'influenceDraft' IS NOT NULL AND NEW.output->'influenceDraft'<>'null'::jsonb THEN
  SELECT COALESCE(max(document.logical_order),0)+1 INTO first_order FROM chapter_documents document JOIN chapter_stable_checkpoints checkpoint ON checkpoint.chapter_document_id=document.id AND checkpoint.body_version_id=document.adopted_version_id AND checkpoint.status='stable' WHERE document.book_id=NEW.book_id AND document.status='active';
  INSERT INTO character_author_influence_candidates(id,book_id,card_id,source_hash,draft,target_start,target_end) VALUES(NEW.id,NEW.book_id,NEW.card_id,NEW.source_snapshot->>'hash',NEW.output->'influenceDraft',first_order,first_order+2) ON CONFLICT(id) DO NOTHING;
 END IF;
 RETURN NEW;
END $$;


