  IF NEW.revision<>OLD.revision+1 OR OLD.status<>'ready' OR NEW.status NOT IN ('consumed','expired','cancelled') THEN RAISE EXCEPTION 'invalid chapter revision preview transition' USING ERRCODE='23514'; END IF;
