--
-- Name: guard_chapter_writing_request(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_chapter_writing_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'chapter writing request cannot be deleted' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(NEW)-ARRAY['ai_task_id','result_body_version_id','status','error_summary','updated_at','controlled_output','controlled_execution']::text[]) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['ai_task_id','result_body_version_id','status','error_summary','updated_at','controlled_output','controlled_execution']::text[]) THEN
    RAISE EXCEPTION 'chapter writing request frozen inputs are immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.status IN ('succeeded','failed','cancelled','stale') THEN RAISE EXCEPTION 'terminal chapter writing request is immutable' USING ERRCODE='23514'; END IF;
  IF OLD.controlled_output IS NOT NULL AND ROW(NEW.controlled_output,NEW.controlled_execution) IS DISTINCT FROM ROW(OLD.controlled_output,OLD.controlled_execution) THEN RAISE EXCEPTION 'controlled model reply is immutable' USING ERRCODE='23514'; END IF;
  IF NEW.controlled_output IS NOT NULL AND (NEW.controlled_snapshot IS NULL OR NEW.controlled_execution IS NULL) THEN RAISE EXCEPTION 'controlled reply requires frozen provenance' USING ERRCODE='23514'; END IF;
  IF NEW.controlled_output IS NOT NULL THEN
    IF jsonb_typeof(NEW.controlled_output->'content') IS DISTINCT FROM 'string' OR length(btrim(NEW.controlled_output->>'content'))=0 OR length(NEW.controlled_output->>'content')>2000000 OR NEW.controlled_output->>'decision' IS NULL OR NEW.controlled_output->>'decision' NOT IN ('continue','continue_with_warning','pause_for_manual','stop_for_replan') OR jsonb_typeof(NEW.controlled_output->'warnings') IS DISTINCT FROM 'array' OR jsonb_typeof(NEW.controlled_output->'reason') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'controlled reply structured fields mismatch' USING ERRCODE='23514'; END IF;
    IF jsonb_array_length(NEW.controlled_output->'warnings')>100 OR length(NEW.controlled_output->>'reason')>4000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.controlled_output->'warnings') warning WHERE jsonb_typeof(warning) IS DISTINCT FROM 'string' OR length(warning#>>'{}') NOT BETWEEN 1 AND 2000) THEN RAISE EXCEPTION 'controlled reply warning boundaries mismatch' USING ERRCODE='23514'; END IF;
  END IF;
  IF OLD.controlled_output IS NULL AND NEW.controlled_output IS NOT NULL AND (OLD.status<>'running' OR NEW.status<>'running' OR NOT EXISTS(
    SELECT 1 FROM ai_task_steps step JOIN ai_task_attempts attempt ON attempt.id=step.current_attempt_id
    WHERE step.task_id=NEW.ai_task_id AND step.lease_expires_at>now() AND attempt.status='running' AND attempt.task_contract_version_id=NEW.task_contract_version_id
      AND attempt.context_manifest_id=NEW.context_manifest_id AND attempt.prompt_recipe_version_id=NEW.prompt_recipe_version_id AND attempt.model_route_snapshot_id=NEW.model_route_snapshot_id)) THEN RAISE EXCEPTION 'controlled reply needs original live attempt' USING ERRCODE='23514'; END IF;
  IF NEW.status<>OLD.status AND NOT (
    (OLD.status='preparing' AND NEW.status IN ('queued','unavailable','cancelled')) OR
    (OLD.status='queued' AND NEW.status IN ('running','succeeded','failed','cancelled','unavailable','stale')) OR
    (OLD.status='running' AND NEW.status IN ('succeeded','failed','cancelled','stale')) OR
    (OLD.status='unavailable' AND NEW.status IN ('preparing','queued','cancelled'))
  ) THEN RAISE EXCEPTION 'illegal chapter writing request transition' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_character_author_influence(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_character_author_influence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'new_design', 'public', 'pg_temp'
    AS $$
DECLARE original character_author_trials%ROWTYPE; material card_versions%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'original influence candidate immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT original FROM character_author_trials WHERE id=NEW.id;
 IF original.status<>'succeeded' OR original.book_id<>NEW.book_id OR original.card_id<>NEW.card_id OR original.source_snapshot->>'hash'<>NEW.source_hash OR original.output->'influenceDraft' IS DISTINCT FROM NEW.draft OR jsonb_typeof(NEW.draft)<>'object' THEN RAISE EXCEPTION 'influence must preserve exact original structured reply' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'draft' OR NEW.revision<>1 OR NEW.guidance_card_id IS NOT NULL THEN RAISE EXCEPTION 'influence begins as unadopted candidate' USING ERRCODE='23514'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','revision','target_start','target_end','guidance_card_id','guidance_version_id','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','target_start','target_end','guidance_card_id','guidance_version_id','updated_at']) OR NEW.revision<>OLD.revision+1 OR OLD.status IN('expired','superseded','dismissed') OR OLD.guidance_card_id IS NOT NULL AND (NEW.guidance_card_id IS DISTINCT FROM OLD.guidance_card_id OR NEW.guidance_version_id IS DISTINCT FROM OLD.guidance_version_id OR NEW.target_start<>OLD.target_start OR NEW.target_end<>OLD.target_end) THEN RAISE EXCEPTION 'original influence provenance and terminal state immutable' USING ERRCODE='23514'; END IF;
  IF NOT (OLD.status='draft' AND NEW.status IN('active','dismissed','expired') OR OLD.status='active' AND NEW.status IN('dismissed','superseded','expired')) THEN RAISE EXCEPTION 'influence transition rejected' USING ERRCODE='23514'; END IF;
  IF NEW.status='active' THEN
   IF NOT EXISTS(SELECT 1 FROM character_author_influence_capability WHERE operational) OR NOT EXISTS(SELECT 1 FROM cards person JOIN books book ON book.space_id=person.space_id WHERE person.id=NEW.card_id AND book.id=NEW.book_id AND person.status='active' AND book.status='active') THEN RAISE EXCEPTION 'influence activation not enabled for this book person' USING ERRCODE='23514'; END IF;
  END IF;
 END IF;
 IF NEW.guidance_version_id IS NOT NULL THEN
  SELECT * INTO STRICT material FROM card_versions WHERE id=NEW.guidance_version_id AND card_id=NEW.guidance_card_id;
  IF (NOT EXISTS(SELECT 1 FROM cards card JOIN card_types type ON type.id=card.card_type_id JOIN books book ON book.space_id=card.space_id WHERE card.id=material.card_id AND book.id=NEW.book_id AND type.type_key='character_author_guidance') OR material.author_book_id IS DISTINCT FROM NEW.book_id OR material.values->>'content_kind'<>'author_selected_creative_guidance' OR material.values->>'source_trial_id'<>NEW.id::text OR material.values->>'character_id'<>NEW.card_id::text OR material.values->>'source_hash'<>NEW.source_hash OR NULLIF(material.values->>'draft_json','')::jsonb IS DISTINCT FROM NEW.draft OR material.values->>'target_start'<>NEW.target_start::text OR material.values->>'target_end'<>NEW.target_end::text) IS DISTINCT FROM false THEN RAISE EXCEPTION 'influence must use original exact author material version' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status='active' AND NEW.guidance_version_id IS NULL THEN RAISE EXCEPTION 'activated influence lacks author material version' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_character_author_influence_decision(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_character_author_influence_decision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'new_design', 'public', 'pg_temp'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'original influence decisions immutable' USING ERRCODE='23514'; END IF;
 IF (NOT EXISTS(SELECT 1 FROM character_author_influence_candidates candidate WHERE candidate.id=NEW.candidate_id AND candidate.book_id=NEW.book_id AND candidate.card_id=NEW.card_id AND candidate.source_hash=NEW.input_payload->>'sourceHash' AND candidate.revision=(NEW.input_payload->>'expectedRevision')::integer+1 AND candidate.target_start=(NEW.input_payload->>'targetStart')::integer AND candidate.target_end=(NEW.input_payload->>'targetEnd')::integer AND candidate.status=CASE WHEN NEW.input_payload->>'action'='activate' THEN 'active' WHEN NEW.input_payload->>'action' IN('dismiss','revoke') THEN 'dismissed' ELSE NULL END AND candidate.revision=(NEW.receipt->'candidate'->>'revision')::integer) OR NEW.input_payload->>'requestKey'<>NEW.request_key::text OR NEW.input_payload->>'candidateId'<>NEW.candidate_id::text OR NEW.input_payload->>'bookId'<>NEW.book_id::text OR NEW.input_payload->>'cardId'<>NEW.card_id::text OR NEW.receipt->>'requestKey'<>NEW.request_key::text OR NEW.receipt->>'inputHash'<>NEW.input_hash OR NEW.receipt->'candidate'->>'id'<>NEW.candidate_id::text OR NEW.receipt->'candidate'->>'bookId'<>NEW.book_id::text OR NEW.receipt->'candidate'->>'cardId'<>NEW.card_id::text) IS DISTINCT FROM false THEN RAISE EXCEPTION 'influence decision scope mismatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_character_author_trial(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_character_author_trial() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'new_design', 'public', 'pg_temp'
    AS $$
DECLARE task ai_tasks%ROWTYPE; step ai_task_steps%ROWTYPE; attempt ai_task_attempts%ROWTYPE; contract task_contract_versions%ROWTYPE; recipe prompt_recipe_versions%ROWTYPE; manifest context_manifests%ROWTYPE; route model_route_snapshots%ROWTYPE; source jsonb; actual jsonb; item jsonb; cutoff_order integer; versions jsonb; expected_count integer:=0;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'character author original evidence immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['status','reply','output','summary']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','reply','output','summary']) OR OLD.status<>'running' AND NEW IS DISTINCT FROM OLD OR OLD.reply IS NOT NULL AND NEW.reply IS DISTINCT FROM OLD.reply THEN RAISE EXCEPTION 'character author input and reply immutable' USING ERRCODE='23514'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM character_author_capability capability WHERE capability.contract='character_author_v1' AND capability.operational) OR NEW.status<>'running' OR NEW.reply IS NOT NULL OR NEW.output IS NOT NULL THEN RAISE EXCEPTION 'character author trials not enabled' USING ERRCODE='23514'; END IF;
 END IF;
 SELECT * INTO STRICT task FROM ai_tasks WHERE id=NEW.id AND book_id=NEW.book_id;
 SELECT * INTO STRICT step FROM ai_task_steps WHERE id=NEW.step_id AND task_id=NEW.id AND current_attempt_id=NEW.attempt_id;
 SELECT * INTO STRICT attempt FROM ai_task_attempts WHERE id=NEW.attempt_id AND task_id=NEW.id AND step_id=NEW.step_id;
 SELECT * INTO STRICT contract FROM task_contract_versions WHERE id=attempt.task_contract_version_id;
 SELECT * INTO STRICT recipe FROM prompt_recipe_versions WHERE id=attempt.prompt_recipe_version_id;
 SELECT * INTO STRICT manifest FROM context_manifests WHERE id=attempt.context_manifest_id;
 SELECT * INTO STRICT route FROM model_route_snapshots WHERE id=attempt.model_route_snapshot_id;
 source:=NEW.source_snapshot;
 IF NOT COALESCE(task.source_kind='character_author' AND task.source_id=NEW.id AND task.request_idempotency_key=NEW.request_key::text AND task.request_hash=NEW.request_hash AND task.task_contract_version_id=contract.id AND step.step_key='character_author' AND step.max_attempts=1 AND attempt.attempt_number=1 AND attempt.input_hash=NEW.frozen_plan->>'inputHash' AND attempt.output_schema_version=NEW.frozen_plan->>'outputSchemaVersion' AND contract.status='published' AND contract.task_group='character_dialogue' AND contract.budget_policy->>'assetId'='new_design.character.author_conversation' AND contract.retry_policy='{"maxAttempts":1,"automaticRetry":false}'::jsonb AND recipe.status='published' AND recipe.id=contract.prompt_recipe_version_id AND recipe.variables_schema->'const'=contract.input_schema->'const' AND contract.input_schema->'const'=NEW.frozen_plan->'promptInput' AND NEW.frozen_plan->'promptInput'->>'contract'='character_author_v1' AND NEW.frozen_plan->'promptInput'->'input'=NEW.input_payload AND NEW.frozen_plan->'promptInput'->'source'=source AND manifest.book_id=NEW.book_id AND manifest.task_contract_version_id=contract.id AND manifest.prompt_recipe_version_id=recipe.id AND manifest.model_route_snapshot_id=route.id AND manifest.source_set_hash=source->>'hash' AND route.snapshot_hash=NEW.frozen_plan->>'snapshotHash' AND route.retry_policy->>'maxRetries'='0' AND NEW.frozen_plan->'route'->'fallbacks'='[]'::jsonb AND NEW.input_payload->>'requestKey'=NEW.request_key::text AND NEW.input_payload->>'bookId'=NEW.book_id::text AND NEW.input_payload->>'cardId'=NEW.card_id::text AND NEW.input_payload->>'sourceHash'=source->>'hash' AND source->>'bookId'=NEW.book_id::text AND source->>'cardId'=NEW.card_id::text AND source->'cutoffBodyVersionId'=NEW.input_payload->'cutoffBodyVersionId',false) THEN RAISE EXCEPTION 'character author frozen contract mismatch' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF task.status<>'running' OR step.status<>'running' OR attempt.status<>'running' OR NEW.input_payload->>'kind' NOT IN ('conversation','scene_analysis') OR jsonb_typeof(NEW.input_payload->'historyKeys')<>'array' THEN RAISE EXCEPTION 'character author original claim mismatch' USING ERRCODE='23514'; END IF;
  SELECT jsonb_build_object('id',id,'name',name,'description',description,'revision',revision) INTO actual FROM books WHERE id=NEW.book_id AND status='active';
  IF actual IS NULL OR actual IS DISTINCT FROM source->'data'->'book' THEN RAISE EXCEPTION 'character author book source mismatch' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('requestKey',prior.request_key,'kind',prior.input_payload->>'kind','message',prior.input_payload->>'message','output',prior.output) ORDER BY prior.created_at,prior.id),'[]'::jsonb),COALESCE(jsonb_agg(prior.request_key ORDER BY prior.created_at,prior.id),'[]'::jsonb) INTO actual,versions FROM character_author_trials prior WHERE prior.book_id=NEW.book_id AND prior.card_id=NEW.card_id AND prior.status='succeeded' AND prior.source_snapshot->>'hash'=source->>'hash';
  IF jsonb_array_length(versions)>100 OR versions IS DISTINCT FROM NEW.input_payload->'historyKeys' OR actual IS DISTINCT FROM NEW.frozen_plan->'promptInput'->'history' THEN RAISE EXCEPTION 'character author causal history mismatch' USING ERRCODE='23514'; END IF;
  SELECT jsonb_build_object('id',card.id,'versionId',version.id,'title',version.title,'typeVersionId',version.type_version_id,'values',version.values,'fields',spec.fields,'localFields',COALESCE((SELECT jsonb_agg(jsonb_build_object('definitionId',definition.id,'versionId',local_spec.id,'field',local_spec.field_schema,'value',local.value) ORDER BY definition.field_key) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id JOIN field_definition_versions local_spec ON local_spec.id=local.field_definition_version_id AND local_spec.field_definition_id=definition.id WHERE local.card_version_id=version.id),'[]'::jsonb)) INTO actual FROM cards card JOIN books book ON book.space_id=card.space_id AND book.id=NEW.book_id AND book.status='active' JOIN card_types type ON type.id=card.card_type_id AND type.type_key='character' JOIN card_versions version ON version.id=card.current_version_id AND version.card_id=card.id JOIN card_type_versions spec ON spec.id=version.type_version_id AND spec.card_type_id=type.id WHERE card.id=NEW.card_id AND card.status='active';
  IF actual IS NULL OR actual IS DISTINCT FROM source->'data'->'profile' THEN RAISE EXCEPTION 'character author profile source mismatch' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',relation.id,'versionId',version.id,'revision',version.revision,'properties',version.properties,'type',jsonb_build_object('id',type.id,'name',type.name,'direction',type.direction,'fields',type.properties_schema,'updatedAt',to_char(type.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),'sourceId',endpoint_source.card_id,'sourceVersionId',endpoint_source.id,'sourceTitle',endpoint_source.title,'targetId',endpoint_target.card_id,'targetVersionId',endpoint_target.id,'targetTitle',endpoint_target.title) ORDER BY relation.id),'[]'::jsonb) INTO actual FROM card_relations relation JOIN books book ON book.space_id=relation.space_id AND book.id=NEW.book_id JOIN relation_types type ON type.id=relation.relation_type_id AND type.status='published' JOIN card_relation_versions version ON version.id=relation.current_version_id AND version.card_relation_id=relation.id AND version.status='active' JOIN card_versions endpoint_source ON endpoint_source.id=version.source_card_version_id AND endpoint_source.card_id=relation.source_card_id JOIN card_versions endpoint_target ON endpoint_target.id=version.target_card_version_id AND endpoint_target.card_id=relation.target_card_id WHERE relation.status='active' AND (relation.source_card_id=NEW.card_id OR relation.target_card_id=NEW.card_id);
  IF actual IS DISTINCT FROM source->'data'->'relations' OR jsonb_array_length(actual)>200 OR EXISTS(SELECT 1 FROM card_relations relation JOIN books book ON book.space_id=relation.space_id AND book.id=NEW.book_id WHERE relation.status='active' AND (relation.source_card_id=NEW.card_id OR relation.target_card_id=NEW.card_id) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual) AS relation_items(relation_item) WHERE relation_items.relation_item->>'id'=relation.id::text)) THEN RAISE EXCEPTION 'character author complete current setting relations mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.input_payload->>'cutoffBodyVersionId' IS NULL THEN
   IF jsonb_array_length(source->'data'->'chapters')<>0 OR EXISTS(SELECT 1 FROM chapter_documents WHERE book_id=NEW.book_id AND status='active' AND adopted_version_id IS NOT NULL) THEN RAISE EXCEPTION 'character author must select occurred chapter range' USING ERRCODE='23514'; END IF;
  ELSE
   SELECT document.logical_order INTO STRICT cutoff_order FROM chapter_documents document JOIN chapter_body_versions body ON body.id=document.adopted_version_id AND body.chapter_document_id=document.id AND body.archived_at IS NULL WHERE document.book_id=NEW.book_id AND document.status='active' AND body.id=(NEW.input_payload->>'cutoffBodyVersionId')::uuid;
   SELECT COALESCE(jsonb_agg(jsonb_build_object('documentId',document.id,'bodyVersionId',body.id,'title',document.title,'order',document.logical_order,'content',body.content,'contentHash',body.content_hash) ORDER BY document.logical_order,document.id),'[]'::jsonb) INTO actual FROM chapter_documents document JOIN chapter_body_versions body ON body.id=document.adopted_version_id AND body.chapter_document_id=document.id AND body.archived_at IS NULL WHERE document.book_id=NEW.book_id AND document.status='active' AND document.logical_order<=cutoff_order;
   IF actual IS DISTINCT FROM source->'data'->'chapters' THEN RAISE EXCEPTION 'character author occurred body versions mismatch' USING ERRCODE='23514'; END IF;
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('stableId',initial.id,'versionId',version.id,'subjectKind',initial.subject_kind,'subjectId',initial.subject_id,'fieldKey',initial.state_key,'value',version.value_json,'kind','initial') ORDER BY initial.subject_kind,initial.subject_id,initial.state_key),'[]'::jsonb) INTO actual FROM entity_initial_states initial JOIN entity_initial_state_versions version ON version.id=initial.current_version_id AND version.initial_state_id=initial.id WHERE initial.book_id=NEW.book_id AND ((initial.subject_kind='card' AND initial.subject_id=NEW.card_id) OR (initial.subject_kind='relation' AND EXISTS(SELECT 1 FROM jsonb_array_elements(source->'data'->'relations') relation WHERE relation->>'id'=initial.subject_id::text)));
  SELECT actual||COALESCE(jsonb_agg(jsonb_build_object('stableId',change.id,'versionId',change.id,'subjectKind',change.subject_kind,'subjectId',change.subject_id,'fieldKey',change.state_key,'value',change.after_json,'chapterOrder',document.logical_order,'sequence',change.sequence::text,'kind','change') ORDER BY document.logical_order,change.sequence,change.id),'[]'::jsonb) INTO actual FROM state_changes change JOIN chapter_documents document ON document.id=change.chapter_document_id AND document.book_id=change.book_id AND document.status='active' AND document.adopted_version_id=change.body_version_id WHERE change.book_id=NEW.book_id AND ((change.subject_kind='card' AND change.subject_id=NEW.card_id) OR (change.subject_kind='relation' AND EXISTS(SELECT 1 FROM jsonb_array_elements(source->'data'->'relations') relation WHERE relation->>'id'=change.subject_id::text))) AND change.status='active' AND document.logical_order<=cutoff_order;
  IF actual IS DISTINCT FROM source->'data'->'states' THEN RAISE EXCEPTION 'character author complete state sources mismatch' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('versionId',change.id,'stableId',change.proposal_id,'claimId',change.claim_id,'stance',change.stance,'predicate',claim.predicate,'value',claim.value_json,'chapterOrder',document.logical_order) ORDER BY document.logical_order,change.id),'[]'::jsonb) INTO actual FROM knowledge_state_changes change JOIN knowledge_state_proposals proposal ON proposal.id=change.proposal_id AND proposal.book_id=change.book_id AND proposal.status='confirmed' AND proposal.confirmed_change_id=change.id JOIN knowledge_state_proposal_versions version ON version.id=change.proposal_version_id AND version.proposal_id=proposal.id JOIN epistemic_claims claim ON claim.id=change.claim_id AND claim.book_id=change.book_id JOIN chapter_documents document ON document.id=version.chapter_document_id AND document.book_id=change.book_id AND document.status='active' AND document.adopted_version_id=version.body_version_id WHERE change.book_id=NEW.book_id AND change.holder_card_id=NEW.card_id AND change.holder_kind='character' AND change.status='active' AND document.logical_order<=cutoff_order;
  IF actual IS DISTINCT FROM source->'data'->'knowledge' THEN RAISE EXCEPTION 'character author complete confirmed knowledge mismatch' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(jsonb_agg(version_id ORDER BY first_order),'[]'::jsonb) INTO versions FROM (SELECT version_id,min(ord) first_order FROM jsonb_array_elements_text(jsonb_build_array(source->'data'->'profile'->'versionId',source->'data'->'profile'->'typeVersionId')||(SELECT COALESCE(jsonb_agg(local->'versionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'profile'->'localFields') WITH ORDINALITY AS locals(local,ord))||(SELECT COALESCE(jsonb_agg(versions.version_id ORDER BY ord,versions.local_order),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'relations') WITH ORDINALITY AS relations(relation,ord) CROSS JOIN LATERAL (VALUES (relation->'versionId',0),(relation->'sourceVersionId',1),(relation->'targetVersionId',2)) AS versions(version_id,local_order))||(SELECT COALESCE(jsonb_agg(chapter->'bodyVersionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'chapters') WITH ORDINALITY AS chapters(chapter,ord))||(SELECT COALESCE(jsonb_agg(state->'versionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'states') WITH ORDINALITY AS states(state,ord))||(SELECT COALESCE(jsonb_agg(knowledge->'versionId' ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(source->'data'->'knowledge') WITH ORDINALITY AS knowledge_sources(knowledge,ord))) WITH ORDINALITY AS cited(version_id,ord) GROUP BY version_id) deduplicated;
  IF versions IS DISTINCT FROM source->'versionIds' THEN RAISE EXCEPTION 'character author exact citation set mismatch' USING ERRCODE='23514'; END IF;
  FOR item IN SELECT DISTINCT expected.item FROM (SELECT jsonb_build_object('kind','card_version','sourceType','card_version','stableId',NEW.card_id,'versionId',source->'data'->'profile'->>'versionId') AS item UNION ALL SELECT jsonb_build_object('kind','card_relation','sourceType','card_relation','stableId',relation->>'id','versionId',relation->>'versionId') FROM jsonb_array_elements(source->'data'->'relations') relation UNION ALL SELECT jsonb_build_object('kind','card_version','sourceType','card_version','stableId',relation->>'sourceId','versionId',relation->>'sourceVersionId') FROM jsonb_array_elements(source->'data'->'relations') relation UNION ALL SELECT jsonb_build_object('kind','card_version','sourceType','card_version','stableId',relation->>'targetId','versionId',relation->>'targetVersionId') FROM jsonb_array_elements(source->'data'->'relations') relation UNION ALL SELECT jsonb_build_object('kind','chapter_body_version','sourceType','body_version','stableId',chapter->>'documentId','versionId',chapter->>'bodyVersionId') FROM jsonb_array_elements(source->'data'->'chapters') chapter UNION ALL SELECT jsonb_build_object('kind',CASE WHEN state->>'kind'='initial' THEN 'entity_initial_state' ELSE 'state_change' END,'sourceType',CASE WHEN state->>'kind'='initial' THEN 'entity_initial_state' ELSE 'state_change' END,'stableId',state->>'stableId','versionId',state->>'versionId') FROM jsonb_array_elements(source->'data'->'states') state UNION ALL SELECT jsonb_build_object('kind','knowledge_state_change','sourceType','knowledge_state_change','stableId',knowledge->>'stableId','versionId',knowledge->>'versionId') FROM jsonb_array_elements(source->'data'->'knowledge') knowledge) expected LOOP
   expected_count:=expected_count+1;
   IF NOT EXISTS(SELECT 1 FROM context_manifest_entries entry CROSS JOIN LATERAL resolve_dependency_resource(item->>'kind',(item->>'stableId')::uuid,(item->>'versionId')::uuid) resolved WHERE entry.manifest_id=manifest.id AND entry.source_type=item->>'sourceType' AND entry.stable_object_id=(item->>'stableId')::uuid AND entry.exact_version_id=(item->>'versionId')::uuid AND entry.content_role='required' AND entry.transform_status='full' AND entry.content_hash=resolved.resolved_hash AND resolved.resolved_book_id=NEW.book_id) THEN RAISE EXCEPTION 'character author manifest exact source missing' USING ERRCODE='23514'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM context_manifest_entries WHERE manifest_id=manifest.id)<>expected_count THEN RAISE EXCEPTION 'character author unexpected manifest source' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.reply IS NOT NULL AND NOT COALESCE(NEW.reply->'output'->>'bookId'=NEW.book_id::text AND NEW.reply->'output'->>'cardId'=NEW.card_id::text AND NEW.reply->'output'->>'sourceHash'=source->>'hash' AND NEW.reply->'execution'->>'routeSnapshotId'=route.id::text AND NEW.reply->'execution'->>'routeSnapshotHash'=route.snapshot_hash AND NEW.reply->'execution'->>'provider'=route.provider AND NEW.reply->'execution'->>'model'=route.model AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.reply->'execution'->'attempts') trace WHERE trace->>'status'='succeeded' AND trace->>'requestSent'='true' AND trace->>'responseReceived'='true'),false) THEN RAISE EXCEPTION 'character author reply original execution mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.reply IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.reply->'output'->'sourceVersionIds') AS cited(version_id) WHERE NOT ((source->'versionIds') ? cited.version_id)) THEN RAISE EXCEPTION 'character author reply cites foreign version' USING ERRCODE='23514'; END IF;
 IF NEW.status='running' AND (NEW.output IS NOT NULL OR task.status<>'running' OR step.status<>'running' OR attempt.status<>'running') THEN RAISE EXCEPTION 'character author running ledger mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.status IN ('succeeded','stale') AND (NEW.reply IS NULL OR NEW.output IS DISTINCT FROM NEW.reply->'output' OR task.status<>'succeeded' OR step.status<>'succeeded' OR attempt.status<>'succeeded') OR NEW.status='failed' AND (NEW.output IS NOT NULL OR task.status<>'failed' OR step.status<>'failed' OR attempt.status<>'failed') OR NEW.status='ended_unknown' AND (NEW.reply IS NOT NULL OR NEW.output IS NOT NULL OR task.status<>'cancelled' OR step.status<>'cancelled' OR attempt.status<>'discarded') THEN RAISE EXCEPTION 'character author terminal ledger mismatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_character_dialogue_round(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_character_dialogue_round() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'dialogue original reply cannot be deleted' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(OLD)-ARRAY['status','model_request_state','generated_output','generated_execution','failure']::text[]) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['status','model_request_state','generated_output','generated_execution','failure']::text[]) THEN RAISE EXCEPTION 'dialogue original freeze immutable' USING ERRCODE='23514'; END IF;
  IF OLD.generated_output IS NOT NULL AND (OLD.generated_output,OLD.generated_execution) IS DISTINCT FROM(NEW.generated_output,NEW.generated_execution) THEN RAISE EXCEPTION 'dialogue original saved reply immutable' USING ERRCODE='23514'; END IF;
  IF OLD.status<>'running' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'dialogue terminal round immutable' USING ERRCODE='23514'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM ai_tasks task JOIN ai_task_steps step ON step.task_id=task.id JOIN ai_task_attempts attempt ON attempt.task_id=task.id AND attempt.step_id=step.id JOIN task_contract_versions contract ON contract.id=attempt.task_contract_version_id JOIN character_dialogue_sessions session ON session.id=NEW.session_id AND session.book_id=NEW.book_id WHERE task.id=NEW.ai_task_id AND task.book_id=NEW.book_id AND task.source_kind='character_dialogue' AND task.source_id=NEW.id AND step.id=NEW.step_id AND step.max_attempts=1 AND step.current_attempt_id=attempt.id AND attempt.id=NEW.attempt_id AND attempt.attempt_number=1 AND attempt.input_hash=NEW.input_hash AND attempt.output_schema_version=contract.output_schema_version AND NEW.frozen_plan->>'sourceHash'=session.frozen_sources->>'hash' AND NEW.input_payload->>'requestKey'=NEW.request_key::text AND NEW.input_payload->>'sourceHash'=session.frozen_sources->>'hash' AND NEW.frozen_plan->'input'->'actor'->>'cardId'=NEW.input_payload->>'actorCardId' AND NEW.frozen_plan->'input'->>'sessionId'=session.id::text AND NEW.frozen_plan->'input'->>'roundId'=NEW.id::text) THEN RAISE EXCEPTION 'dialogue true original attempt and source mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.generated_output IS NOT NULL AND (NEW.generated_execution IS NULL OR jsonb_typeof(NEW.generated_output)<>'object' OR jsonb_typeof(NEW.generated_execution)<>'object' OR NEW.model_request_state<>'completed' OR NEW.generated_execution->>'routeSnapshotId' IS DISTINCT FROM NEW.frozen_plan->>'snapshotId' OR NEW.generated_execution->>'routeSnapshotHash' IS DISTINCT FROM NEW.frozen_plan->>'snapshotHash' OR NEW.generated_execution->>'provider' IS DISTINCT FROM NEW.frozen_plan->'route'->'primary'->>'provider' OR NEW.generated_execution->>'model' IS DISTINCT FROM NEW.frozen_plan->'route'->'primary'->>'model' OR NEW.generated_output->>'actorCardId' IS DISTINCT FROM NEW.input_payload->>'actorCardId' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(NEW.generated_execution->'attempts','[]'::jsonb)) execution WHERE execution->>'status'='succeeded' AND execution->>'requestSent'='true' AND execution->>'responseReceived'='true')) THEN RAISE EXCEPTION 'dialogue saved reply requires true received execution' USING ERRCODE='23514'; END IF;
 IF NEW.status='succeeded' AND (NEW.generated_output IS NULL OR NOT EXISTS(SELECT 1 FROM ai_task_attempts WHERE id=NEW.attempt_id AND status='succeeded')) THEN RAISE EXCEPTION 'dialogue success requires original saved reply and completed attempt' USING ERRCODE='23514'; END IF;
 IF NEW.status='ended_unknown' AND NEW.generated_output IS NOT NULL THEN RAISE EXCEPTION 'saved dialogue reply cannot be unknown' USING ERRCODE='23514'; END IF;RETURN NEW;
END $$;


--
-- Name: guard_character_dialogue_selection(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_character_dialogue_selection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $$ DECLARE original_round character_dialogue_rounds; original_version planning_versions; saved_version planning_versions; appended jsonb; selected_count integer; BEGIN
 IF NEW.input_payload->>'requestKey' IS DISTINCT FROM NEW.request_key::text OR NEW.input_payload->>'planningObjectId' IS DISTINCT FROM NEW.planning_object_id::text OR jsonb_typeof(NEW.input_payload->'actionKeys') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dialogue original action input required' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM character_dialogue_rounds round JOIN character_dialogue_sessions session ON session.id=round.session_id AND session.book_id=round.book_id JOIN planning_versions version ON version.id=NEW.planning_version_id AND version.object_id=NEW.planning_object_id AND version.book_id=NEW.book_id JOIN planning_operation_events event ON event.version_id=version.id AND event.object_id=version.object_id AND event.book_id=version.book_id WHERE round.id=NEW.round_id AND round.session_id=NEW.session_id AND round.book_id=NEW.book_id AND round.status='succeeded' AND round.generated_output IS NOT NULL AND version.source='user' AND version.status IN('draft','proposed') AND event.action='revise' AND event.idempotency_key=NEW.request_key::text AND event.expected_revision::text=NEW.input_payload->>'expectedPlanningRevision' AND NEW.input_payload->>'roundId'=round.id::text AND NEW.input_payload->>'sourceHash'=session.frozen_sources->>'hash') THEN RAISE EXCEPTION 'dialogue selected actions require original successful round and real planning candidate' USING ERRCODE='23514'; END IF;
 SELECT * INTO original_round FROM character_dialogue_rounds WHERE id=NEW.round_id;
 SELECT * INTO saved_version FROM planning_versions WHERE id=NEW.planning_version_id;
 SELECT * INTO original_version FROM planning_versions WHERE id=saved_version.base_version_id AND id::text=NEW.input_payload->>'planningVersionId' AND object_id=NEW.planning_object_id AND book_id=NEW.book_id;
 selected_count:=jsonb_array_length(NEW.input_payload->'actionKeys');
 IF original_version.id IS NULL OR selected_count NOT BETWEEN 1 AND 20 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(NEW.input_payload->'actionKeys'))<>selected_count THEN RAISE EXCEPTION 'dialogue original planning basis or selected keys invalid' USING ERRCODE='23514'; END IF;
 SELECT jsonb_agg(action->'constraint' ORDER BY selected.ordinality) INTO appended FROM jsonb_array_elements_text(NEW.input_payload->'actionKeys') WITH ORDINALITY selected(key,ordinality) JOIN LATERAL jsonb_array_elements(original_round.generated_output->'actions') action ON action->>'key'=selected.key;
 IF appended IS NULL OR jsonb_array_length(appended)<>selected_count OR jsonb_typeof(original_version.content->'constraints') IS DISTINCT FROM 'array' OR (saved_version.content-'constraints') IS DISTINCT FROM (original_version.content-'constraints') OR saved_version.content->'constraints' IS DISTINCT FROM ((original_version.content->'constraints')||appended) OR saved_version.execution_mode IS DISTINCT FROM original_version.execution_mode OR saved_version.based_on_parent_version_id IS DISTINCT FROM original_version.based_on_parent_version_id OR saved_version.source_body_version_id IS NOT NULL THEN RAISE EXCEPTION 'dialogue may only append exact selected constraints to original planning draft' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(saved_version.content->'constraints')>100 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(appended))<>selected_count OR EXISTS(SELECT 1 FROM jsonb_array_elements(appended) chosen JOIN jsonb_array_elements(original_version.content->'constraints') prior ON chosen.value=prior.value) THEN RAISE EXCEPTION 'dialogue duplicate or excessive new constraints prohibited' USING ERRCODE='23514'; END IF;
 IF (SELECT COALESCE(jsonb_agg(jsonb_build_array(reference_role,card_id,card_version_id,action_key,note,sort_order) ORDER BY reference_role,card_id,action_key),'[]'::jsonb) FROM planning_version_references WHERE planning_version_id=saved_version.id) IS DISTINCT FROM (SELECT COALESCE(jsonb_agg(jsonb_build_array(reference_role,card_id,card_version_id,action_key,note,sort_order) ORDER BY reference_role,card_id,action_key),'[]'::jsonb) FROM planning_version_references WHERE planning_version_id=original_version.id) THEN RAISE EXCEPTION 'dialogue selected constraints cannot replace original planning references' USING ERRCODE='23514'; END IF;RETURN NEW;
END $$;


--
-- Name: guard_character_dialogue_session(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_character_dialogue_session() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'dialogue sandbox history cannot be deleted' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND ((to_jsonb(OLD)-'revision') IS DISTINCT FROM (to_jsonb(NEW)-'revision') OR NEW.revision<>OLD.revision+1) THEN RAISE EXCEPTION 'dialogue sources and original input immutable' USING ERRCODE='23514'; END IF;
 IF NEW.frozen_sources->>'bookId' IS DISTINCT FROM NEW.book_id::text OR NEW.input_payload->>'requestKey' IS DISTINCT FROM NEW.request_key::text OR NEW.frozen_sources->>'hash' IS DISTINCT FROM NEW.input_payload->>'sourceHash' OR NOT EXISTS(SELECT 1 FROM chapter_stable_checkpoints checkpoint JOIN chapter_documents document ON document.id=checkpoint.chapter_document_id AND document.book_id=checkpoint.book_id WHERE checkpoint.id::text=NEW.input_payload->>'checkpointId' AND checkpoint.book_id=NEW.book_id AND checkpoint.body_version_id::text=NEW.frozen_sources->'checkpoint'->>'bodyVersionId') THEN RAISE EXCEPTION 'dialogue cutoff source identity mismatch' USING ERRCODE='23514'; END IF;RETURN NEW;
END $$;


--
-- Name: guard_consumer_update(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_consumer_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'consumer registration cannot be deleted' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(NEW)-ARRAY['status','revision','pause_reason','updated_at']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','pause_reason','updated_at']::text[]) THEN RAISE EXCEPTION 'consumer registration is immutable' USING ERRCODE='23514'; END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'consumer revision must advance by one' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


