--
-- Name: guard_f8_append_only(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_f8_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN RAISE EXCEPTION '% is append-only',TG_TABLE_NAME USING ERRCODE='23514'; END $$;


--
-- Name: guard_finalized_context_snapshot(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_finalized_context_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE target_manifest_id uuid; target_status text;
BEGIN
  IF TG_TABLE_NAME='context_manifests' THEN
    IF OLD.status='finalized' THEN RAISE EXCEPTION 'finalized context manifests are immutable' USING ERRCODE='23514'; END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  target_manifest_id:=OLD.manifest_id;
  SELECT status INTO target_status FROM context_manifests WHERE id=target_manifest_id;
  IF target_status='finalized' THEN RAISE EXCEPTION 'finalized context manifest children are immutable' USING ERRCODE='23514'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_graph_projection_history(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_graph_projection_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN RAISE EXCEPTION 'graph projection history is append-only' USING ERRCODE='23514'; END $$;


--
-- Name: guard_graph_projection_mapping(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_graph_projection_mapping() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'graph projection mappings are append-only' USING ERRCODE='23514'; END IF;
  IF OLD.status<>'active' OR NEW.status<>'tombstoned' OR NEW.tombstoned_at IS NULL OR
     (to_jsonb(NEW)-ARRAY['status','tombstoned_at']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','tombstoned_at']::text[]) THEN
    RAISE EXCEPTION 'graph projection mapping may only be tombstoned' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_graph_projection_transition(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_graph_projection_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_TABLE_NAME='graph_projection_requests' THEN
    IF (to_jsonb(NEW)-ARRAY['status','attempt_count','last_error_code','last_error_detail','retryable','started_at','completed_at','generation_id']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','attempt_count','last_error_code','last_error_detail','retryable','started_at','completed_at','generation_id']::text[]) THEN RAISE EXCEPTION 'graph projection request identity is immutable' USING ERRCODE='23514'; END IF;
    IF NOT ((OLD.status='pending' AND NEW.status IN ('processing','superseded')) OR (OLD.status='processing' AND NEW.status IN ('succeeded','failed')) OR (OLD.status='failed' AND NEW.status='processing')) THEN RAISE EXCEPTION 'invalid graph projection request transition' USING ERRCODE='23514'; END IF;
  ELSIF TG_TABLE_NAME='graph_projection_generations' THEN
    IF (to_jsonb(NEW)-ARRAY['status','source_watermark','vertex_count','edge_count','projection_checksum','error_code','error_detail','retryable','completed_at','activated_at']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','source_watermark','vertex_count','edge_count','projection_checksum','error_code','error_detail','retryable','completed_at','activated_at']::text[]) THEN RAISE EXCEPTION 'graph generation identity is immutable' USING ERRCODE='23514'; END IF;
    IF NOT ((OLD.status='building' AND NEW.status IN ('ready','failed')) OR (OLD.status='ready' AND NEW.status IN ('active','failed')) OR (OLD.status='active' AND NEW.status IN ('active','superseded'))) THEN RAISE EXCEPTION 'invalid graph generation transition' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_image_preparation(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_image_preparation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $_$
DECLARE task ai_tasks%ROWTYPE; step ai_task_steps%ROWTYPE; attempt ai_task_attempts%ROWTYPE; contract task_contract_versions%ROWTYPE; recipe prompt_recipe_versions%ROWTYPE; manifest context_manifests%ROWTYPE; snapshot model_route_snapshots%ROWTYPE; source jsonb; item jsonb; actual jsonb; target_book books%ROWTYPE; profile jsonb; card_count integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'image preparation immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['status','reply','output','summary']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','reply','output','summary']) OR OLD.status<>'running' AND NEW IS DISTINCT FROM OLD OR OLD.reply IS NOT NULL AND NEW.reply IS DISTINCT FROM OLD.reply OR NEW.status='running' AND (NEW.output IS NOT NULL OR NEW.summary IS DISTINCT FROM OLD.summary) THEN RAISE EXCEPTION 'image preparation original input and reply immutable' USING ERRCODE='23514'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM image_preparation_capability capability WHERE capability.contract='image_prompt_preparation_v1' AND capability.operational) OR NEW.status<>'running' OR NEW.reply IS NOT NULL OR NEW.output IS NOT NULL THEN RAISE EXCEPTION 'image preparation not enabled' USING ERRCODE='23514'; END IF;
 END IF;
 SELECT * INTO STRICT task FROM ai_tasks WHERE id=NEW.id;
 SELECT * INTO STRICT step FROM ai_task_steps WHERE id=NEW.step_id AND task_id=NEW.id AND current_attempt_id=NEW.attempt_id;
 SELECT * INTO STRICT attempt FROM ai_task_attempts WHERE id=NEW.attempt_id AND task_id=NEW.id AND step_id=NEW.step_id;
 SELECT * INTO STRICT contract FROM task_contract_versions WHERE id=attempt.task_contract_version_id;
 SELECT * INTO STRICT recipe FROM prompt_recipe_versions WHERE id=attempt.prompt_recipe_version_id;
 SELECT * INTO STRICT manifest FROM context_manifests WHERE id=attempt.context_manifest_id;
 SELECT * INTO STRICT snapshot FROM model_route_snapshots WHERE id=attempt.model_route_snapshot_id;
 source:=NEW.source_snapshot;
 IF jsonb_typeof(source)<>'object' OR source-ARRAY['scope','hash','data']<>'{}'::jsonb OR NEW.input_payload-ARRAY['requestKey','scope','sourceHash','original']<>'{}'::jsonb OR source->>'hash' !~ '^[a-f0-9]{64}$' OR NEW.request_hash !~ '^[a-f0-9]{64}$' OR jsonb_typeof(NEW.input_payload->'original')<>'string' OR length(btrim(NEW.input_payload->>'original')) NOT BETWEEN 1 AND 1000000 OR NEW.frozen_plan->>'contractVersionId' IS DISTINCT FROM contract.id::text OR NEW.frozen_plan->>'recipeVersionId' IS DISTINCT FROM recipe.id::text OR NEW.frozen_plan->>'manifestId' IS DISTINCT FROM manifest.id::text OR NEW.frozen_plan->>'snapshotId' IS DISTINCT FROM snapshot.id::text THEN RAISE EXCEPTION 'image preparation input shape mismatch' USING ERRCODE='23514'; END IF;
 IF NOT COALESCE(task.source_kind='image_prompt_preparation' AND task.source_id=NEW.id AND task.request_idempotency_key=NEW.request_key::text AND task.request_hash=NEW.request_hash AND task.task_contract_version_id=contract.id AND step.step_key='image_prompt_preparation' AND step.max_attempts=1 AND attempt.attempt_number=1 AND attempt.input_hash=NEW.frozen_plan->>'inputHash' AND attempt.output_schema_version=NEW.frozen_plan->>'outputSchemaVersion' AND contract.task_group='form_assist' AND contract.status='published' AND contract.budget_policy->>'assetId'='new_design.image.prompt_preparation' AND contract.budget_policy->>'assetVersion'='v1' AND contract.retry_policy='{"maxAttempts":1,"automaticRetry":false}'::jsonb AND recipe.id=contract.prompt_recipe_version_id AND recipe.status='published' AND recipe.variables_schema->'const'=contract.input_schema->'const' AND contract.input_schema->'const'=NEW.frozen_plan->'promptInput' AND NEW.frozen_plan->'promptInput'->'source'=source AND NEW.frozen_plan->'promptInput'->>'original'=NEW.input_payload->>'original' AND source->'scope'=NEW.input_payload->'scope' AND source->>'hash'=NEW.input_payload->>'sourceHash' AND manifest.task_contract_version_id=contract.id AND manifest.prompt_recipe_version_id=recipe.id AND manifest.model_route_snapshot_id=snapshot.id AND manifest.source_set_hash=source->>'hash' AND snapshot.snapshot_hash=NEW.frozen_plan->>'snapshotHash' AND snapshot.provider=NEW.frozen_plan->'route'->'primary'->>'provider' AND snapshot.model=NEW.frozen_plan->'route'->'primary'->>'model' AND snapshot.retry_policy->>'maxRetries'='0' AND NEW.frozen_plan->'route'->'fallbacks'='[]'::jsonb,false) THEN RAISE EXCEPTION 'image preparation frozen contract mismatch' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  IF task.status<>'running' OR step.status<>'running' OR attempt.status<>'running' OR NEW.input_payload->>'requestKey'<>NEW.request_key::text THEN RAISE EXCEPTION 'image preparation claim mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.input_payload->'scope'->>'kind'='book' THEN
   IF (NEW.input_payload->'scope')-ARRAY['kind','bookId']<>'{}'::jsonb OR (source->'data')-ARRAY['book','cards','plans']<>'{}'::jsonb THEN RAISE EXCEPTION 'image preparation book source shape mismatch' USING ERRCODE='23514'; END IF;
   SELECT * INTO STRICT target_book FROM books WHERE id=NEW.scope_id AND status='active';
   IF task.book_id IS DISTINCT FROM target_book.id OR manifest.book_id IS DISTINCT FROM target_book.id OR NEW.input_payload->'scope'->>'bookId'<>target_book.id::text OR source->'data'->'book' IS DISTINCT FROM jsonb_build_object('id',target_book.id,'name',target_book.name,'description',target_book.description,'revision',target_book.revision) THEN RAISE EXCEPTION 'image preparation book mismatch' USING ERRCODE='23514'; END IF;
   SELECT count(*) INTO card_count FROM cards WHERE space_id=target_book.space_id AND status='active';
   IF jsonb_array_length(source->'data'->'cards')<>card_count OR (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(source->'data'->'cards'))<>card_count THEN RAISE EXCEPTION 'image preparation incomplete card set' USING ERRCODE='23514'; END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(source->'data'->'cards') LOOP
    SELECT jsonb_build_object('id',card.id,'versionId',version.id,'title',version.title,'typeVersionId',version.type_version_id,'values',version.values,'fields',spec.fields,'localFields',COALESCE((SELECT jsonb_agg(jsonb_build_object('definitionId',definition.id,'versionId',local_spec.id,'field',local_spec.field_schema,'value',local.value) ORDER BY definition.field_key) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id JOIN field_definition_versions local_spec ON local_spec.id=local.field_definition_version_id AND local_spec.field_definition_id=definition.id WHERE local.card_version_id=version.id),'[]'::jsonb)) INTO actual FROM cards card JOIN card_versions version ON version.id=card.current_version_id AND version.card_id=card.id JOIN card_type_versions spec ON spec.id=version.type_version_id WHERE card.id=(item->>'id')::uuid AND card.space_id=target_book.space_id AND card.status='active';
    IF actual IS DISTINCT FROM item THEN RAISE EXCEPTION 'image preparation actual card mismatch' USING ERRCODE='23514'; END IF;
   END LOOP;
   SELECT COALESCE(jsonb_agg(jsonb_build_object('id',object.id,'versionId',version.id,'level',object.level,'title',object.title,'content',version.content,'contentHash',version.content_hash) ORDER BY object.id),'[]'::jsonb) INTO actual FROM planning_objects object JOIN planning_versions version ON version.id=object.adopted_version_id AND version.object_id=object.id WHERE object.book_id=target_book.id AND object.status='active' AND object.level='story' AND version.status='adopted' AND version.stale_at IS NULL;
   IF actual IS DISTINCT FROM source->'data'->'plans' THEN RAISE EXCEPTION 'image preparation story source mismatch' USING ERRCODE='23514'; END IF;
  ELSIF NEW.input_payload->'scope'->>'kind'='public_character' THEN
   profile:=source->'data'->'profile';
   IF (NEW.input_payload->'scope')-ARRAY['kind','resourceId','resourceVersionId']<>'{}'::jsonb OR (source->'data')-ARRAY['profile']<>'{}'::jsonb OR profile-ARRAY['id','versionId','revision','typeVersionId','title','values','fields','localFields','hash']<>'{}'::jsonb OR profile->>'hash' !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'image preparation public source shape mismatch' USING ERRCODE='23514'; END IF;
   IF task.book_id IS NOT NULL OR manifest.book_id IS NOT NULL OR manifest.public_character_scope IS DISTINCT FROM NEW.scope_id OR NEW.input_payload->'scope'->>'resourceId'<>NEW.scope_id::text OR profile->>'id'<>NEW.scope_id::text OR profile->>'versionId'<>NEW.input_payload->'scope'->>'resourceVersionId' OR NOT EXISTS(SELECT 1 FROM cards card JOIN card_types type ON type.id=card.card_type_id JOIN card_versions version ON version.card_id=card.id JOIN card_type_versions spec ON spec.id=version.type_version_id WHERE card.id=NEW.scope_id AND card.space_id='60000000-0000-4000-8000-000000000001' AND card.status='active' AND type.type_key='character' AND type.status='published' AND version.id=(profile->>'versionId')::uuid AND version.title=profile->>'title' AND version.revision=(profile->>'revision')::integer AND version.type_version_id=(profile->>'typeVersionId')::uuid AND profile->'values'=version.values||COALESCE((SELECT jsonb_object_agg(definition.field_key,local.value) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id WHERE local.card_version_id=version.id),'{}'::jsonb) AND profile->'fields'=spec.fields||COALESCE((SELECT jsonb_agg(field.field_schema ORDER BY definition.field_key) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id JOIN field_definition_versions field ON field.id=local.field_definition_version_id AND field.field_definition_id=definition.id WHERE local.card_version_id=version.id),'[]'::jsonb) AND profile->'localFields'=COALESCE((SELECT jsonb_agg(jsonb_build_object('definitionId',definition.id,'versionId',field.id,'field',field.field_schema,'value',local.value) ORDER BY definition.field_key) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id JOIN field_definition_versions field ON field.id=local.field_definition_version_id AND field.field_definition_id=definition.id WHERE local.card_version_id=version.id),'[]'::jsonb)) THEN RAISE EXCEPTION 'image preparation public source mismatch' USING ERRCODE='23514'; END IF;
  ELSE RAISE EXCEPTION 'image preparation unknown scope' USING ERRCODE='23514'; END IF;
 END IF;
 IF TG_OP='INSERT' THEN
  IF (SELECT count(*) FROM context_manifest_entries WHERE manifest_id=manifest.id)<>(CASE WHEN task.book_id IS NULL THEN 1 ELSE jsonb_array_length(source->'data'->'cards')+jsonb_array_length(source->'data'->'plans') END) OR EXISTS(
   SELECT 1 FROM context_manifest_entries entry WHERE entry.manifest_id=manifest.id AND NOT COALESCE(
    entry.transform_status='full' AND entry.content_role='required' AND entry.token_estimate>=0 AND (
     task.book_id IS NULL AND entry.source_type='card_version' AND entry.stable_object_id=NEW.scope_id AND entry.exact_version_id=(NEW.input_payload->'scope'->>'resourceVersionId')::uuid OR
     task.book_id IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(source->'data'->'cards') card WHERE entry.source_type='card_version' AND entry.stable_object_id=(card->>'id')::uuid AND entry.exact_version_id=(card->>'versionId')::uuid) OR
     task.book_id IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(source->'data'->'plans') plan WHERE entry.source_type='planning_version' AND entry.stable_object_id=(plan->>'id')::uuid AND entry.exact_version_id=(plan->>'versionId')::uuid)
    ),false)) OR (SELECT count(DISTINCT (source_type,stable_object_id,exact_version_id)) FROM context_manifest_entries WHERE manifest_id=manifest.id)<>(SELECT count(*) FROM context_manifest_entries WHERE manifest_id=manifest.id) THEN
   RAISE EXCEPTION 'image preparation manifest sources mismatch' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.reply IS NOT NULL AND NOT COALESCE(NEW.reply->'output'->>'sourceHash'=source->>'hash' AND jsonb_typeof(NEW.reply->'output'->'chinese')='string' AND length(btrim(NEW.reply->'output'->>'chinese')) BETWEEN 1 AND 4000 AND jsonb_typeof(NEW.reply->'output'->'english')='string' AND length(btrim(NEW.reply->'output'->>'english')) BETWEEN 1 AND 4000 AND NEW.reply->'execution'->>'routeSnapshotId'=snapshot.id::text AND NEW.reply->'execution'->>'routeSnapshotHash'=snapshot.snapshot_hash AND NEW.reply->'execution'->>'provider'=snapshot.provider AND NEW.reply->'execution'->>'model'=snapshot.model AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.reply->'execution'->'attempts') trace WHERE trace->>'status'='succeeded' AND trace->>'requestSent'='true' AND trace->>'responseReceived'='true'),false) THEN RAISE EXCEPTION 'image preparation actual reply mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.reply IS NOT NULL AND (NEW.reply-ARRAY['output','execution']<>'{}'::jsonb OR (NEW.reply->'output')-ARRAY['sourceHash','chinese','english','missingInformation']<>'{}'::jsonb OR jsonb_typeof(NEW.reply->'output'->'missingInformation')<>'array' OR jsonb_array_length(NEW.reply->'output'->'missingInformation')>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.reply->'output'->'missingInformation') value WHERE jsonb_typeof(value)<>'string' OR length(value#>>'{}')>500)) THEN RAISE EXCEPTION 'image preparation reply shape mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.status='failed' AND (task.status<>'failed' OR step.status<>'failed' OR attempt.status<>'failed') OR NEW.status='ended_unknown' AND (NEW.reply IS NOT NULL OR task.status<>'cancelled' OR step.status<>'cancelled' OR attempt.status<>'discarded') THEN RAISE EXCEPTION 'image preparation terminal ledger mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.status='succeeded' AND (NEW.reply IS NULL OR NEW.output IS DISTINCT FROM NEW.reply->'output' OR task.status<>'succeeded' OR step.status<>'succeeded' OR attempt.status<>'succeeded') OR NEW.status IN ('failed','ended_unknown') AND NEW.output IS NOT NULL THEN RAISE EXCEPTION 'image preparation terminal mismatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_knowledge_build_receipt(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_knowledge_build_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'new_design', 'public', 'pg_temp'
    AS $$ BEGIN
 IF OLD.knowledge_build_hash IS NOT NULL AND NEW.knowledge_build_hash IS DISTINCT FROM OLD.knowledge_build_hash THEN RAISE EXCEPTION 'immutable knowledge build receipt' USING ERRCODE='23514'; END IF; RETURN NEW;
END $$;


--
-- Name: guard_knowledge_embedding_execution(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_knowledge_embedding_execution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'new_design', 'public', 'pg_temp'
    AS $$
DECLARE frozen jsonb; chunk embedding_chunks%ROWTYPE; source embedding_source_snapshots%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='embedding_profile_versions' THEN
  IF NEW.connection_version_id IS NOT NULL THEN
   PERFORM validate_knowledge_embedding_freeze(jsonb_build_object('connectionVersionId',NEW.connection_version_id,'connectionHash',(SELECT content_hash FROM model_route_versions WHERE id=NEW.connection_version_id),'profileVersionId',NEW.id,'profileHash',NEW.content_hash,'provider',NEW.provider_key,'model',NEW.model_key,'dimensions',NEW.dimensions,'inputHash',NEW.content_hash),NEW.id);
  END IF;
 ELSIF TG_TABLE_NAME='chunking_requests' THEN
  IF NEW.knowledge_index_key IS NOT NULL AND (NEW.knowledge_index_hash IS NULL OR jsonb_typeof(NEW.knowledge_index_plan) IS DISTINCT FROM 'object') THEN RAISE EXCEPTION 'incomplete index receipt' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND OLD.knowledge_index_key IS NOT NULL AND (NEW.knowledge_index_key IS DISTINCT FROM OLD.knowledge_index_key OR NEW.knowledge_index_hash IS DISTINCT FROM OLD.knowledge_index_hash OR NEW.knowledge_index_plan IS DISTINCT FROM OLD.knowledge_index_plan) THEN RAISE EXCEPTION 'immutable index receipt' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='embedding_attempts' THEN
  SELECT embedding_freeze INTO frozen FROM embedding_requests WHERE id=NEW.request_id;
  IF TG_OP='INSERT' AND frozen IS NOT NULL AND NEW.attempt_number<>1 THEN RAISE EXCEPTION 'controlled embedding cannot be sent twice' USING ERRCODE='23514'; END IF;
  IF NEW.embedding_reply IS NOT NULL THEN
   SELECT embedding_freeze INTO frozen FROM embedding_requests WHERE id=NEW.request_id;
   IF frozen IS NULL OR NEW.embedding_reply->>'provider' IS DISTINCT FROM frozen->>'provider' OR NEW.embedding_reply->>'model' IS DISTINCT FROM frozen->>'model'
   OR jsonb_array_length(NEW.embedding_reply->'vector') IS DISTINCT FROM (frozen->>'dimensions')::integer OR NEW.embedding_reply->>'responseReceived' IS DISTINCT FROM 'true'
   THEN RAISE EXCEPTION 'embedding reply does not match original attempt' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.embedding_reply IS NOT NULL AND (NEW.embedding_reply_hash IS NULL OR jsonb_typeof(NEW.embedding_reply) IS DISTINCT FROM 'object') THEN RAISE EXCEPTION 'incomplete embedding reply' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND OLD.embedding_reply IS NOT NULL AND (NEW.embedding_reply IS DISTINCT FROM OLD.embedding_reply OR NEW.embedding_reply_hash IS DISTINCT FROM OLD.embedding_reply_hash) THEN RAISE EXCEPTION 'immutable embedding reply' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.embedding_freeze IS NOT NULL THEN PERFORM validate_knowledge_embedding_freeze(NEW.embedding_freeze,NEW.profile_version_id); END IF;
  IF TG_OP='UPDATE' AND OLD.embedding_freeze IS NOT NULL AND NEW.embedding_freeze IS DISTINCT FROM OLD.embedding_freeze THEN RAISE EXCEPTION 'immutable embedding input' USING ERRCODE='23514'; END IF;
  IF TG_OP='UPDATE' AND OLD.embedding_lease_expires_at IS NOT NULL AND NEW.embedding_lease_expires_at IS DISTINCT FROM OLD.embedding_lease_expires_at THEN RAISE EXCEPTION 'immutable embedding lease' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME='embedding_requests' THEN
   IF NEW.embedding_freeze IS NOT NULL THEN
    SELECT * INTO chunk FROM embedding_chunks WHERE id=NEW.chunk_id; SELECT * INTO source FROM embedding_source_snapshots WHERE id=chunk.source_snapshot_id;
    IF (NEW.embedding_freeze->>'bookId')::uuid IS DISTINCT FROM NEW.book_id OR (NEW.embedding_freeze->>'requestId')::uuid IS DISTINCT FROM NEW.id
    OR (NEW.embedding_freeze->>'chunkId')::uuid IS DISTINCT FROM NEW.chunk_id OR (NEW.embedding_freeze->>'sourceSnapshotId')::uuid IS DISTINCT FROM source.id
    OR (NEW.embedding_freeze->>'sourceStableId')::uuid IS DISTINCT FROM source.source_stable_id OR (NEW.embedding_freeze->>'sourceVersionId')::uuid IS DISTINCT FROM source.source_version_id
    OR NEW.embedding_freeze->>'sourceHash' IS DISTINCT FROM NEW.expected_source_hash::text OR NEW.embedding_freeze->>'chunkHash' IS DISTINCT FROM NEW.expected_chunk_hash::text
    THEN RAISE EXCEPTION 'embedding freeze does not match original source identity' USING ERRCODE='23514'; END IF;
   END IF;
   IF NEW.embedding_freeze IS NOT NULL AND NEW.status='running' AND NEW.embedding_execution_key IS NULL THEN RAISE EXCEPTION 'controlled embedding requires original execution receipt' USING ERRCODE='23514'; END IF;
   IF TG_OP='UPDATE' AND OLD.embedding_execution_key IS NOT NULL AND NEW.embedding_execution_key IS DISTINCT FROM OLD.embedding_execution_key THEN RAISE EXCEPTION 'immutable embedding execution key' USING ERRCODE='23514'; END IF;
  ELSE
   IF TG_OP='UPDATE' AND OLD.embedding_reply IS NOT NULL AND (NEW.embedding_reply IS DISTINCT FROM OLD.embedding_reply OR NEW.embedding_reply_hash IS DISTINCT FROM OLD.embedding_reply_hash) THEN RAISE EXCEPTION 'immutable query reply' USING ERRCODE='23514'; END IF;
   IF NEW.embedding_reply IS NOT NULL AND (NEW.embedding_reply_hash IS NULL OR jsonb_typeof(NEW.embedding_reply) IS DISTINCT FROM 'object') THEN RAISE EXCEPTION 'incomplete query reply' USING ERRCODE='23514'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_knowledge_embedding_result(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_knowledge_embedding_result() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'new_design', 'public', 'pg_temp'
    AS $$
DECLARE frozen jsonb; reply jsonb;
BEGIN
 SELECT request.embedding_freeze,attempt.embedding_reply INTO frozen,reply FROM embedding_requests request JOIN embedding_attempts attempt ON attempt.request_id=request.id AND attempt.id=NEW.attempt_id WHERE request.id=NEW.request_id;
 IF frozen IS NOT NULL AND NEW.outcome='applied' AND (reply IS NULL OR NEW.vector_value IS DISTINCT FROM (reply->'vector')::text::vector) THEN RAISE EXCEPTION 'controlled result must equal retained original vector' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_managed_knowledge_derivation(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_managed_knowledge_derivation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $$
BEGIN
 IF NEW.recipe_key='knowledge.utf8' AND current_setting('new_design.knowledge_write',true) IS DISTINCT FROM 'managed' THEN RAISE EXCEPTION 'knowledge parsing requires explicit controlled parsing, not a generic worker result' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_managed_knowledge_version(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_managed_knowledge_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'public'
    AS $_$
DECLARE kind text; registered asset_content_objects%ROWTYPE;
BEGIN
 kind:=NEW.metadata->'knowledgeReference'->>'kind';
 IF EXISTS(SELECT 1 FROM asset_derivations request WHERE request.output_asset_id=NEW.asset_id AND request.recipe_key='knowledge.utf8') AND kind IS DISTINCT FROM 'parsed' THEN RAISE EXCEPTION 'managed knowledge output cannot be replaced by an unrelated asset version' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM assets asset JOIN asset_versions current_version ON current_version.id=asset.current_version_id WHERE asset.id=NEW.asset_id AND current_version.metadata->'knowledgeReference'->>'kind'='source') AND kind IS DISTINCT FROM 'source' THEN RAISE EXCEPTION 'managed knowledge source cannot be silently replaced by another upload workflow' USING ERRCODE='23514'; END IF;
 IF kind IN ('source','parsed') THEN
  IF current_setting('new_design.knowledge_write',true) IS DISTINCT FROM 'managed' THEN RAISE EXCEPTION 'managed knowledge versions require the controlled upload or parse workflow' USING ERRCODE='23514'; END IF;
  SELECT * INTO registered FROM asset_content_objects WHERE id=NEW.content_object_id;
  IF registered.storage_kind<>'managed_file' OR registered.storage_provider<>'local' OR registered.integrity_state<>'verified' OR registered.storage_locator !~ '^knowledge-[a-f0-9]{64}\.utf8$' THEN RAISE EXCEPTION 'knowledge version requires verified controlled text content' USING ERRCODE='23514'; END IF;
  IF kind='parsed' THEN
   IF jsonb_typeof(NEW.metadata->'knowledgeReference'->'text') IS DISTINCT FROM 'string' OR length(NEW.metadata->'knowledgeReference'->>'text')=0 OR NEW.source_kind<>'derived' OR registered.checksum<>encode(sha256(convert_to(NEW.metadata->'knowledgeReference'->>'text','UTF8')),'hex') OR NOT EXISTS(SELECT 1 FROM asset_derivations request WHERE request.recipe_key='knowledge.utf8' AND request.tool_key='knowledge.utf8' AND request.status='processing' AND request.output_asset_id=NEW.asset_id AND request.source_asset_version_id=NEW.derived_from_version_id AND request.book_id=NEW.book_id) THEN RAISE EXCEPTION 'knowledge parse output does not match its exact controlled request and content hash' USING ERRCODE='23514'; END IF;
  ELSIF NEW.source_kind<>'upload' THEN RAISE EXCEPTION 'knowledge source must be a controlled upload' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_material_group_tree(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_material_group_tree() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE parent_row material_groups%ROWTYPE;
BEGIN
  IF NEW.parent_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.parent_id=NEW.id THEN RAISE EXCEPTION 'a material group cannot be its own parent' USING ERRCODE='23514'; END IF;
  SELECT * INTO parent_row FROM material_groups WHERE id=NEW.parent_id;
  IF parent_row.id IS NULL THEN RAISE EXCEPTION 'material group parent not found' USING ERRCODE='23503'; END IF;
  IF parent_row.space_id<>NEW.space_id OR parent_row.book_id IS DISTINCT FROM NEW.book_id THEN
    RAISE EXCEPTION 'cross-space or cross-book material group parent is forbidden' USING ERRCODE='23514';
  END IF;
  IF parent_row.status<>'active' THEN RAISE EXCEPTION 'archived material group cannot be a parent' USING ERRCODE='23514'; END IF;
  IF EXISTS(
    WITH RECURSIVE ancestors(id,parent_id,path) AS (
      SELECT parent.id,parent.parent_id,ARRAY[parent.id] FROM material_groups parent WHERE parent.id=NEW.parent_id
      UNION ALL
      SELECT parent.id,parent.parent_id,ancestors.path||parent.id FROM ancestors
      JOIN material_groups parent ON parent.id=ancestors.parent_id
      WHERE NOT parent.id=ANY(ancestors.path)
    ) SELECT 1 FROM ancestors WHERE id=NEW.id
  ) THEN RAISE EXCEPTION 'material group cycle is forbidden' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


