--
-- Name: guard_material_membership_scope(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_material_membership_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE owner_space uuid; card_space uuid;
BEGIN
  SELECT space_id INTO card_space FROM cards WHERE id=NEW.card_id;
  IF TG_TABLE_NAME='material_tag_memberships' THEN SELECT space_id INTO owner_space FROM material_tags WHERE id=NEW.tag_id;
  ELSE SELECT space_id INTO owner_space FROM material_groups WHERE id=NEW.group_id; END IF;
  IF owner_space IS NULL OR card_space IS NULL THEN RAISE EXCEPTION 'material membership reference not found' USING ERRCODE='23503'; END IF;
  IF owner_space<>NEW.space_id OR card_space<>NEW.space_id THEN RAISE EXCEPTION 'cross-space material membership is forbidden' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_material_tag_tree(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_material_tag_tree() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE parent_dimension uuid;
BEGIN
  IF NEW.parent_id IS NULL THEN RETURN NEW; END IF;
  SELECT dimension_id INTO parent_dimension FROM material_tags WHERE id=NEW.parent_id;
  IF parent_dimension IS NULL OR parent_dimension<>NEW.dimension_id THEN RAISE EXCEPTION '标签节点的上级必须在同一维度中'; END IF;
  IF NEW.parent_id=NEW.id OR EXISTS(
    WITH RECURSIVE descendants AS (
      SELECT id FROM material_tags WHERE parent_id=NEW.id
      UNION ALL SELECT tag.id FROM material_tags tag JOIN descendants parent ON tag.parent_id=parent.id
    ) SELECT 1 FROM descendants WHERE id=NEW.parent_id
  ) THEN RAISE EXCEPTION '标签树不能形成循环'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_outbox_aggregate_sequence(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_outbox_aggregate_sequence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'outbox aggregate sequence cannot be deleted' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(NEW)-ARRAY['last_sequence','updated_at']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['last_sequence','updated_at']::text[]) OR NEW.last_sequence<=OLD.last_sequence THEN RAISE EXCEPTION 'outbox aggregate sequence can only advance' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


