--
-- Name: guard_stable_checkpoint_origin(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_stable_checkpoint_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='DELETE' OR (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') THEN
    RAISE EXCEPTION 'stable checkpoint history and confirmation summary are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


