--
-- Name: invalidate_chapter_initial_source(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.invalidate_chapter_initial_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE previous uuid; replacement uuid;
BEGIN
  IF OLD.current_version_id IS NOT NULL AND NEW.current_version_id IS DISTINCT FROM OLD.current_version_id THEN
    previous:=register_dependency_resource('entity_initial_state',OLD.id,OLD.current_version_id);
    IF NEW.current_version_id IS NOT NULL THEN replacement:=register_dependency_resource('entity_initial_state',NEW.id,NEW.current_version_id); END IF;
    PERFORM invalidate_registered_resource(previous,replacement,'初始状态来源变化','system',NEW.id,'initial-source:'||NEW.id::text||':'||NEW.revision::text);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: invalidate_registered_resource(uuid, uuid, text, text, uuid, text, text); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.invalidate_registered_resource(old_resource uuid, new_resource uuid, event_reason text, event_source text, event_trigger uuid, event_key text, event_state text DEFAULT 'stale'::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE target_book uuid;
BEGIN
  FOR target_book IN SELECT DISTINCT book_id FROM dependency_edges WHERE source_resource_id=old_resource AND status='active' LOOP
    PERFORM record_dependency_invalidation(gen_random_uuid(),target_book,old_resource,new_resource,event_reason,event_source,event_state,event_trigger,event_key || ':' || target_book::text);
  END LOOP;
END $$;


