--
-- Name: reconcile_chapter_revision_after_checkpoint(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.reconcile_chapter_revision_after_checkpoint() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE execution_row chapter_revision_executions%ROWTYPE; pending_count integer;
BEGIN
  SELECT * INTO execution_row FROM chapter_revision_executions
  WHERE chapter_document_id=NEW.chapter_document_id AND new_body_version_id=NEW.body_version_id
    AND status IN ('queued','running','awaiting_review','partially_failed','failed')
  ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;
  SELECT count(*) INTO pending_count FROM chapter_revision_review_flags WHERE execution_id=execution_row.id AND status IN ('pending_review','in_review');
  UPDATE chapter_revision_executions SET status=CASE WHEN pending_count=0 THEN 'stable' ELSE 'awaiting_review' END,current_step=total_steps,revision=revision+1,error_summary='',updated_at=now(),completed_at=CASE WHEN pending_count=0 THEN now() ELSE NULL END WHERE id=execution_row.id;
  IF pending_count=0 THEN UPDATE chapter_revision_plans SET status='completed',revision=revision+1,updated_at=now() WHERE id=execution_row.plan_id AND status='executing'; END IF;
  INSERT INTO chapter_revision_events(id,preview_id,plan_id,execution_id,event_kind,actor,detail)
  VALUES(gen_random_uuid(),execution_row.preview_id,execution_row.plan_id,execution_row.id,CASE WHEN pending_count=0 THEN 'execution_completed' ELSE 'step_updated' END,'system',jsonb_build_object('stableCheckpointId',NEW.id,'pendingReviewCount',pending_count));
  RETURN NEW;
END $$;


--
-- Name: reconcile_chapter_revision_after_review(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.reconcile_chapter_revision_after_review() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE execution_row chapter_revision_executions%ROWTYPE; pending_count integer; stable_exists boolean;
BEGIN
  IF NEW.status NOT IN ('resolved','retained','cancelled') THEN RETURN NEW; END IF;
  SELECT * INTO execution_row FROM chapter_revision_executions WHERE id=NEW.execution_id FOR UPDATE;
  SELECT count(*) INTO pending_count FROM chapter_revision_review_flags WHERE execution_id=NEW.execution_id AND status IN ('pending_review','in_review');
  SELECT EXISTS(SELECT 1 FROM chapter_stable_checkpoints WHERE chapter_document_id=execution_row.chapter_document_id AND body_version_id=execution_row.new_body_version_id AND status='stable') INTO stable_exists;
  IF pending_count=0 AND stable_exists AND execution_row.status NOT IN ('stable','cancelled','dead_letter') THEN
    UPDATE chapter_revision_executions SET status='stable',current_step=total_steps,revision=revision+1,error_summary='',updated_at=now(),completed_at=now() WHERE id=execution_row.id;
    UPDATE chapter_revision_plans SET status='completed',revision=revision+1,updated_at=now() WHERE id=execution_row.plan_id AND status='executing';
    INSERT INTO chapter_revision_events(id,preview_id,plan_id,execution_id,event_kind,actor,detail) VALUES(gen_random_uuid(),execution_row.preview_id,execution_row.plan_id,execution_row.id,'execution_completed','system',jsonb_build_object('reviewFlagId',NEW.id));
  END IF;
  RETURN NEW;
END $$;


--
-- Name: record_dependency_invalidation(uuid, uuid, uuid, uuid, text, text, text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.record_dependency_invalidation(event_uuid uuid, event_book_id uuid, old_resource uuid, new_resource uuid, event_reason text, event_source text, event_state text, event_trigger_id uuid, event_idempotency_key text, preview_id uuid DEFAULT NULL::uuid, change_set_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE event_space_id uuid; existing_id uuid; old_book_id uuid; new_book_id uuid;
BEGIN
  SELECT id INTO existing_id FROM dependency_invalidation_events WHERE book_id=event_book_id AND idempotency_key=event_idempotency_key;
  IF existing_id IS NOT NULL THEN RETURN existing_id; END IF;
  SELECT space_id INTO event_space_id FROM books WHERE id=event_book_id;
  IF event_space_id IS NULL THEN RAISE EXCEPTION 'book not found for invalidation' USING ERRCODE='23503'; END IF;
  SELECT book_id INTO old_book_id FROM dependency_resources WHERE id=old_resource;
  IF NOT FOUND OR (old_book_id IS NOT NULL AND old_book_id IS DISTINCT FROM event_book_id) THEN
    RAISE EXCEPTION 'old dependency resource does not belong to invalidation book' USING ERRCODE='23514';
  END IF;
  IF new_resource IS NOT NULL THEN
    SELECT book_id INTO new_book_id FROM dependency_resources WHERE id=new_resource;
    IF NOT FOUND OR (new_book_id IS NOT NULL AND new_book_id IS DISTINCT FROM event_book_id) THEN
      RAISE EXCEPTION 'new dependency resource does not belong to invalidation book' USING ERRCODE='23514';
    END IF;
  END IF;
  INSERT INTO dependency_invalidation_events(id,space_id,book_id,old_resource_id,new_resource_id,change_preview_id,book_change_set_id,reason,trigger_source,requested_state,trigger_id,idempotency_key)
  VALUES(event_uuid,event_space_id,event_book_id,old_resource,new_resource,preview_id,change_set_id,event_reason,event_source,event_state,event_trigger_id,event_idempotency_key);

  WITH RECURSIVE walk(resource_id,depth,path,strength) AS (
    SELECT edge.derived_resource_id,1,ARRAY[edge.source_resource_id,edge.derived_resource_id],edge.dependency_strength
    FROM dependency_edges edge WHERE edge.book_id=event_book_id AND edge.source_resource_id=old_resource AND edge.status='active'
    UNION ALL
    SELECT edge.derived_resource_id,walk.depth+1,walk.path||edge.derived_resource_id,
      CASE WHEN walk.strength='hard' OR edge.dependency_strength='hard' THEN 'hard' ELSE 'soft' END
    FROM walk JOIN dependency_edges edge ON edge.source_resource_id=walk.resource_id AND edge.book_id=event_book_id AND edge.status='active'
    WHERE NOT edge.derived_resource_id=ANY(walk.path) AND walk.depth<99
  ), ranked AS (
    SELECT DISTINCT ON(resource_id) resource_id,depth,path,strength FROM walk ORDER BY resource_id,depth
  )
  INSERT INTO dependency_invalidation_impacts(id,event_id,resource_id,depth,propagation_path,dependency_strength,impact_state)
  SELECT gen_random_uuid(),event_uuid,resource_id,depth,path,strength,
    CASE WHEN event_state='invalid' AND strength='soft' THEN 'needs_review' ELSE event_state END
  FROM ranked;

  INSERT INTO dependency_stale_reasons(id,book_id,resource_id,event_id,impact_id,state,reason)
  SELECT gen_random_uuid(),event_book_id,impact.resource_id,event_uuid,impact.id,impact.impact_state,event_reason
  FROM dependency_invalidation_impacts impact WHERE impact.event_id=event_uuid;

  INSERT INTO dependency_state_events(id,book_id,resource_id,invalidation_event_id,from_state,to_state,event_kind,detail)
  SELECT gen_random_uuid(),event_book_id,impact.resource_id,event_uuid,state.state,impact.impact_state,'invalidated',event_reason
  FROM dependency_invalidation_impacts impact LEFT JOIN dependency_resource_states state ON state.resource_id=impact.resource_id
  WHERE impact.event_id=event_uuid;

  INSERT INTO dependency_resource_states(resource_id,book_id,state,last_event_id)
  SELECT impact.resource_id,event_book_id,impact.impact_state,event_uuid FROM dependency_invalidation_impacts impact WHERE impact.event_id=event_uuid
  ON CONFLICT(resource_id) DO UPDATE SET state=excluded.state,last_event_id=excluded.last_event_id,revision=dependency_resource_states.revision+1,updated_at=now();

  INSERT INTO dependency_recompute_requests(id,book_id,target_resource_id,invalidation_event_id,required_upstream_versions,priority,reason,strategy_key,idempotency_key)
  SELECT gen_random_uuid(),event_book_id,impact.resource_id,event_uuid,
    COALESCE((SELECT jsonb_agg(jsonb_build_object('resourceId',source.id,'kind',source.resource_kind,'stableObjectId',source.stable_object_id,'exactVersionId',source.exact_version_id,'contentHash',source.content_hash) ORDER BY source.id)
      FROM dependency_edges edge JOIN dependency_resources source ON source.id=edge.source_resource_id
      WHERE edge.derived_resource_id=impact.resource_id AND edge.book_id=event_book_id AND edge.status='active'),'[]'::jsonb),
    CASE WHEN impact.dependency_strength='hard' THEN 50 ELSE 0 END-impact.depth,event_reason,'manual_review',event_uuid::text || ':' || impact.resource_id::text
  FROM dependency_invalidation_impacts impact WHERE impact.event_id=event_uuid;

  INSERT INTO dependency_state_events(id,book_id,resource_id,invalidation_event_id,from_state,to_state,event_kind,detail)
  SELECT gen_random_uuid(),event_book_id,impact.resource_id,event_uuid,impact.impact_state,'recompute_pending','recompute_requested',event_reason
  FROM dependency_invalidation_impacts impact WHERE impact.event_id=event_uuid;
  UPDATE dependency_resource_states SET state='recompute_pending',revision=revision+1,updated_at=now()
  WHERE resource_id IN (SELECT resource_id FROM dependency_invalidation_impacts WHERE event_id=event_uuid);
  RETURN event_uuid;
END $$;


--
-- Name: register_dependency_resource(text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.register_dependency_resource(kind text, stable_id uuid, version_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE resource_id uuid;
BEGIN
  SELECT id INTO resource_id FROM dependency_resources WHERE resource_kind=kind AND stable_object_id=stable_id AND exact_version_id=version_id;
  IF resource_id IS NOT NULL THEN RETURN resource_id; END IF;
  resource_id:=gen_random_uuid();
  INSERT INTO dependency_resources(id,resource_kind,stable_object_id,exact_version_id,content_hash)
  VALUES(resource_id,kind,stable_id,version_id,''::char(64))
  ON CONFLICT(resource_kind,stable_object_id,exact_version_id) DO NOTHING;
  RETURN (SELECT id FROM dependency_resources WHERE resource_kind=kind AND stable_object_id=stable_id AND exact_version_id=version_id);
END $$;


--
-- Name: register_material_membership_dependency(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.register_material_membership_dependency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE membership_card_id uuid; membership_owner_id uuid; owner_kind text; owner_version_id uuid; membership_book_id uuid;
BEGIN
  IF TG_TABLE_NAME='material_tag_membership_versions' THEN
    SELECT membership.card_id,membership.tag_id,book.id INTO membership_card_id,membership_owner_id,membership_book_id FROM material_tag_memberships membership LEFT JOIN books book ON book.space_id=membership.space_id WHERE membership.id=NEW.membership_id;
    owner_kind:='tag_version'; owner_version_id:=NEW.tag_version_id;
  ELSE
    SELECT membership.card_id,membership.group_id,book.id INTO membership_card_id,membership_owner_id,membership_book_id FROM material_group_memberships membership LEFT JOIN books book ON book.space_id=membership.space_id WHERE membership.id=NEW.membership_id;
    owner_kind:='material_group_version'; owner_version_id:=NEW.group_version_id;
  END IF;
  IF membership_book_id IS NULL THEN
    PERFORM register_dependency_resource(owner_kind,membership_owner_id,owner_version_id);
    PERFORM register_dependency_resource('card_version',membership_card_id,NEW.card_version_id);
    PERFORM register_dependency_resource(CASE WHEN owner_kind='tag_version' THEN 'tag_membership' ELSE 'group_membership' END,NEW.membership_id,NEW.id);
  ELSIF owner_kind='tag_version' THEN
    PERFORM add_registered_dependency(owner_kind,membership_owner_id,owner_version_id,'tag_membership',NEW.membership_id,NEW.id,'configured_by','soft','manual',NEW.id);
    PERFORM add_registered_dependency('card_version',membership_card_id,NEW.card_version_id,'tag_membership',NEW.membership_id,NEW.id,'configured_by','soft','manual',NEW.id);
  ELSE
    PERFORM add_registered_dependency(owner_kind,membership_owner_id,owner_version_id,'group_membership',NEW.membership_id,NEW.id,'configured_by','soft','manual',NEW.id);
    PERFORM add_registered_dependency('card_version',membership_card_id,NEW.card_version_id,'group_membership',NEW.membership_id,NEW.id,'configured_by','soft','manual',NEW.id);
  END IF;
  RETURN NEW;
END $$;


