    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    revision integer DEFAULT 1 NOT NULL,
    preparation_contract text,
    preparation_request_key text,
    preparation_request_hash text,
    frozen_plan jsonb,
    model_route_snapshot_id uuid,
    preparation_lease_until timestamp with time zone,
    preparation_generated_output jsonb,
    preparation_execution jsonb,
    preparation_failure jsonb,
    preparation_terminal text,
    preparation_superseded_by uuid,
    preparation_adoption_receipts jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT ai_generation_batches_frozen_plan_check CHECK (((frozen_plan IS NULL) OR (jsonb_typeof(frozen_plan) = 'object'::text))),
    CONSTRAINT ai_generation_batches_operation_check CHECK ((operation = ANY (ARRAY['directions'::text, 'initial_content'::text, 'form_assist'::text]))),
    CONSTRAINT ai_generation_batches_preparation_adoption_receipts_check CHECK ((jsonb_typeof(preparation_adoption_receipts) = 'array'::text)),
    CONSTRAINT ai_generation_batches_preparation_contract_check CHECK (((preparation_contract IS NULL) OR (preparation_contract = 'creation_preparation_v1'::text))),
    CONSTRAINT ai_generation_batches_preparation_execution_check CHECK (((preparation_execution IS NULL) OR (jsonb_typeof(preparation_execution) = 'object'::text))),
    CONSTRAINT ai_generation_batches_preparation_failure_check CHECK (((preparation_failure IS NULL) OR (jsonb_typeof(preparation_failure) = 'object'::text))),
    CONSTRAINT ai_generation_batches_preparation_generated_output_check CHECK (((preparation_generated_output IS NULL) OR (jsonb_typeof(preparation_generated_output) = 'object'::text))),
    CONSTRAINT ai_generation_batches_preparation_request_hash_check CHECK (((preparation_request_hash IS NULL) OR (preparation_request_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ai_generation_batches_preparation_request_key_check CHECK (((preparation_request_key IS NULL) OR ((length(preparation_request_key) >= 8) AND (length(preparation_request_key) <= 160)))),
    CONSTRAINT ai_generation_batches_preparation_terminal_check CHECK (((preparation_terminal IS NULL) OR (preparation_terminal = ANY (ARRAY['released'::text, 'ended_unknown'::text])))),
    CONSTRAINT ai_generation_batches_progress_check CHECK (((progress >= 0) AND (progress <= 100))),
    CONSTRAINT ai_generation_batches_revision_check CHECK ((revision > 0)),
    CONSTRAINT ai_generation_batches_status_check CHECK ((status = ANY (ARRAY['running'::text, 'review'::text, 'applied'::text, 'failed'::text, 'discarded'::text]))),
    CONSTRAINT creation_preparation_complete CHECK ((((preparation_contract IS NULL) AND (num_nonnulls(preparation_request_key, preparation_request_hash, frozen_plan, model_route_snapshot_id, preparation_lease_until, preparation_generated_output, preparation_execution, preparation_failure, preparation_terminal, preparation_superseded_by) = 0)) OR ((preparation_contract = 'creation_preparation_v1'::text) AND (session_id IS NOT NULL) AND (book_id IS NULL) AND (card_id IS NULL) AND (base_revision IS NOT NULL) AND (num_nonnulls(preparation_request_key, preparation_request_hash, frozen_plan, model_route_snapshot_id, preparation_lease_until) = 5))))
);


