-- Name: book_creation_sessions; Type: TABLE; Schema: new_design; Owner: -
--

CREATE TABLE new_design.book_creation_sessions (
    id uuid NOT NULL,
    method text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    stage text DEFAULT 'collect_input'::text NOT NULL,
    progress integer DEFAULT 0 NOT NULL,
    template_version_id uuid NOT NULL,
    book_name text DEFAULT ''::text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    source_reference text DEFAULT ''::text NOT NULL,
    input_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    direction_candidates jsonb DEFAULT '[]'::jsonb NOT NULL,
    selected_direction_id text,
    initial_cards jsonb DEFAULT '[]'::jsonb NOT NULL,
    last_failed_stage text,
    error_message text,
    book_id uuid,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    review_cards jsonb DEFAULT '[]'::jsonb NOT NULL,
    creation_request_key text,
    creation_request_hash text,
    formal_review jsonb,
    production_receipts jsonb DEFAULT '[]'::jsonb NOT NULL,
    director_control_receipts jsonb DEFAULT '[]'::jsonb NOT NULL,
    director_active_command_key text,
    director_command_failure jsonb,
    CONSTRAINT book_creation_request_complete CHECK ((num_nonnulls(creation_request_key, creation_request_hash) = ANY (ARRAY[0, 2]))),
    CONSTRAINT book_creation_sessions_creation_request_hash_check CHECK (((creation_request_hash IS NULL) OR (creation_request_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT book_creation_sessions_creation_request_key_check CHECK (((creation_request_key IS NULL) OR ((length(creation_request_key) >= 8) AND (length(creation_request_key) <= 160)))),
    CONSTRAINT book_creation_sessions_director_active_command_key_check CHECK (((director_active_command_key IS NULL) OR ((length(director_active_command_key) >= 8) AND (length(director_active_command_key) <= 160)))),
    CONSTRAINT book_creation_sessions_director_command_failure_check CHECK (((director_command_failure IS NULL) OR (jsonb_typeof(director_command_failure) = 'object'::text))),
    CONSTRAINT book_creation_sessions_director_control_receipts_check CHECK ((jsonb_typeof(director_control_receipts) = 'array'::text)),
    CONSTRAINT book_creation_sessions_formal_review_check CHECK (((formal_review IS NULL) OR (jsonb_typeof(formal_review) = 'object'::text))),
    CONSTRAINT book_creation_sessions_method_check CHECK ((method = ANY (ARRAY['blank'::text, 'template'::text, 'idea'::text, 'inspiration'::text, 'market'::text, 'reference'::text, 'continuation'::text]))),
    CONSTRAINT book_creation_sessions_production_receipts_check CHECK ((jsonb_typeof(production_receipts) = 'array'::text)),
    CONSTRAINT book_creation_sessions_progress_check CHECK (((progress >= 0) AND (progress <= 100))),
    CONSTRAINT book_creation_sessions_review_cards_check CHECK ((jsonb_typeof(review_cards) = 'array'::text)),
    CONSTRAINT book_creation_sessions_revision_check CHECK ((revision > 0)),
    CONSTRAINT book_creation_sessions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'generating'::text, 'waiting_direction'::text, 'review'::text, 'creating'::text, 'completed'::text, 'failed'::text])))
);


