--
-- Name: canonical_facts; Type: TABLE; Schema: new_design; Owner: -
--

CREATE TABLE new_design.canonical_facts (
    id uuid NOT NULL,
    book_id uuid NOT NULL,
    subject_card_id uuid NOT NULL,
    predicate text NOT NULL,
    value_kind text NOT NULL,
    value_json jsonb NOT NULL,
    value_hash character(64) NOT NULL,
    object_card_id uuid,
    valid_story_start numeric,
    valid_story_end numeric,
    status text DEFAULT 'proposed'::text NOT NULL,
    confidence numeric(5,4),
    source_method text NOT NULL,
    supersedes_fact_id uuid,
    superseded_by_fact_id uuid,
    revision integer DEFAULT 1 NOT NULL,
    created_by text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT canonical_facts_check CHECK (((valid_story_end IS NULL) OR (valid_story_start IS NULL) OR (valid_story_end >= valid_story_start))),
    CONSTRAINT canonical_facts_check1 CHECK ((((value_kind = 'card_reference'::text) AND (object_card_id IS NOT NULL)) OR ((value_kind <> 'card_reference'::text) AND (object_card_id IS NULL)))),
    CONSTRAINT canonical_facts_check2 CHECK (((supersedes_fact_id IS NULL) OR (supersedes_fact_id <> id))),
    CONSTRAINT canonical_facts_check3 CHECK (((superseded_by_fact_id IS NULL) OR (superseded_by_fact_id <> id))),
    CONSTRAINT canonical_facts_confidence_check CHECK (((confidence IS NULL) OR ((confidence >= (0)::numeric) AND (confidence <= (1)::numeric)))),
    CONSTRAINT canonical_facts_revision_check CHECK ((revision > 0)),
    CONSTRAINT canonical_facts_source_method_check CHECK ((source_method = ANY (ARRAY['manual'::text, 'ai_extract'::text, 'import'::text, 'system'::text]))),
    CONSTRAINT canonical_facts_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'confirmed'::text, 'rejected'::text, 'superseded'::text, 'stale'::text]))),
    CONSTRAINT canonical_facts_value_kind_check CHECK ((value_kind = ANY (ARRAY['text'::text, 'number'::text, 'boolean'::text, 'json'::text, 'card_reference'::text])))
);


