--
-- Name: card_reverse_references; Type: VIEW; Schema: new_design; Owner: -
--

CREATE VIEW new_design.card_reverse_references AS
 SELECT id AS card_id,
    ( SELECT count(*) AS count
           FROM new_design.card_mounts mount
          WHERE ((mount.card_id = card.id) AND (mount.status = 'active'::text))) AS active_mount_count,
    ( SELECT count(*) AS count
           FROM new_design.card_relations relation
          WHERE (((relation.source_card_id = card.id) OR (relation.target_card_id = card.id)) AND (relation.status = 'active'::text))) AS active_relation_count
   FROM new_design.cards card;


