    CONSTRAINT context_bindings_check1 CHECK ((((scope_kind = ANY (ARRAY['public'::text, 'book'::text, 'volume'::text, 'chapter'::text, 'scene'::text, 'one_time'::text])) AND (space_id IS NOT NULL)) OR ((scope_kind = ANY (ARRAY['system'::text, 'task_group'::text, 'task_node'::text])) AND (space_id IS NULL)))),
