    CONSTRAINT context_manifest_exclusions_reason_code_check CHECK ((reason_code = ANY (ARRAY['invalid_reference'::text, 'wrong_book'::text, 'wrong_version'::text, 'slot_type_mismatch'::text, 'lower_priority'::text, 'token_budget'::text, 'duplicate'::text, 'stale'::text, 'unavailable'::text]))),
    CONSTRAINT context_manifest_exclusions_sort_order_check CHECK ((sort_order >= 0)),
    CONSTRAINT context_manifest_exclusions_token_estimate_check CHECK (((token_estimate IS NULL) OR (token_estimate >= 0)))
);


