--
-- Name: material_card_organization; Type: VIEW; Schema: new_design; Owner: -
--

CREATE VIEW new_design.material_card_organization AS
 SELECT id AS card_id,
    space_id,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', tag.id, 'key', tag.tag_key, 'name', version.name, 'color', version.color) ORDER BY version.name) AS jsonb_agg
           FROM ((new_design.material_tag_memberships membership
             JOIN new_design.material_tags tag ON ((tag.id = membership.tag_id)))
             JOIN new_design.material_tag_versions version ON ((version.id = tag.current_version_id)))
          WHERE ((membership.card_id = card.id) AND (membership.status = 'active'::text) AND (tag.status = 'active'::text))), '[]'::jsonb) AS tags,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', group_row.id, 'key', group_row.group_key, 'name', version.name, 'parentId', group_row.parent_id) ORDER BY group_row.sort_order, version.name) AS jsonb_agg
           FROM ((new_design.material_group_memberships membership
             JOIN new_design.material_groups group_row ON ((group_row.id = membership.group_id)))
             JOIN new_design.material_group_versions version ON ((version.id = group_row.current_version_id)))
          WHERE ((membership.card_id = card.id) AND (membership.status = 'active'::text) AND (group_row.status = 'active'::text))), '[]'::jsonb) AS groups
   FROM new_design.cards card;


