    CONSTRAINT world_fix_adoption_shape CHECK ((((chapter_body_adoption_id IS NOT NULL) AND (adopted_body_version_id IS NOT NULL) AND (adopted_card_version_id IS NULL) AND (num_nonnulls(author_write_request_key, world_repair_request_hash, world_repair_input) = 0)) OR ((chapter_body_adoption_id IS NULL) AND (adopted_body_version_id IS NULL) AND (adopted_card_version_id IS NOT NULL) AND (num_nonnulls(author_write_request_key, world_repair_request_hash, world_repair_input) = 3) AND (world_repair_request_hash ~ '^[0-9a-f]{64}$'::text) AND (jsonb_typeof(world_repair_input) = 'object'::text) AND ((world_repair_input ->> 'authorWriteRequestKey'::text) IS NOT NULL) AND ((world_repair_input ->> 'requestKey'::text) IS NOT NULL) AND ((world_repair_input ->> 'authorWriteRequestKey'::text) = (author_write_request_key)::text) AND ((world_repair_input ->> 'requestKey'::text) = idempotency_key))))
);


