--
-- Name: quality_issue_evidence; Type: TABLE; Schema: new_design; Owner: -
--

CREATE TABLE new_design.quality_issue_evidence (
    id uuid NOT NULL,
    issue_version_id uuid NOT NULL,
    evidence_kind text NOT NULL,
    text_anchor_id uuid,
    fact_id uuid,
    state_change_id uuid,
    story_timing_id uuid,
    story_relation_id uuid,
    planning_version_id uuid,
    rule_key text,
    rule_version text,
    note text NOT NULL,
    is_unverified_observation boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    material_kind text,
    material_id uuid,
    card_version_id uuid,
    relation_version_id uuid,
    field_key text,
    field_spec_version_id uuid,
    field_spec_hash character(64),
    observed_value_hash character(64),
    CONSTRAINT quality_issue_evidence_check CHECK ((((evidence_kind = 'text_anchor'::text) AND (text_anchor_id IS NOT NULL) AND (num_nonnulls(fact_id, state_change_id, story_timing_id, story_relation_id, planning_version_id) = 0)) OR ((evidence_kind = 'canonical_fact'::text) AND (fact_id IS NOT NULL) AND (num_nonnulls(text_anchor_id, state_change_id, story_timing_id, story_relation_id, planning_version_id) = 0)) OR ((evidence_kind = 'state_change'::text) AND (state_change_id IS NOT NULL) AND (num_nonnulls(text_anchor_id, fact_id, story_timing_id, story_relation_id, planning_version_id) = 0)) OR ((evidence_kind = 'story_time'::text) AND (story_timing_id IS NOT NULL) AND (num_nonnulls(text_anchor_id, fact_id, state_change_id, story_relation_id, planning_version_id) = 0)) OR ((evidence_kind = 'story_relation'::text) AND (story_relation_id IS NOT NULL) AND (num_nonnulls(text_anchor_id, fact_id, state_change_id, story_timing_id, planning_version_id) = 0)) OR ((evidence_kind = 'planning_version'::text) AND (planning_version_id IS NOT NULL) AND (num_nonnulls(text_anchor_id, fact_id, state_change_id, story_timing_id, story_relation_id) = 0)) OR ((evidence_kind = 'rule'::text) AND (rule_key IS NOT NULL) AND (rule_version IS NOT NULL) AND (num_nonnulls(text_anchor_id, fact_id, state_change_id, story_timing_id, story_relation_id, planning_version_id) = 0)) OR ((evidence_kind = 'observation'::text) AND is_unverified_observation AND (num_nonnulls(text_anchor_id, fact_id, state_change_id, story_timing_id, story_relation_id, planning_version_id) = 0)) OR ((evidence_kind = ANY (ARRAY['card_field'::text, 'relation_field'::text])) AND (material_id IS NOT NULL) AND (field_key IS NOT NULL) AND (field_spec_hash IS NOT NULL) AND (observed_value_hash IS NOT NULL) AND (NOT is_unverified_observation) AND (num_nonnulls(text_anchor_id, fact_id, state_change_id, story_timing_id, story_relation_id, planning_version_id, rule_key, rule_version) = 0)))),
    CONSTRAINT quality_issue_evidence_evidence_kind_check CHECK (((evidence_kind = ANY (ARRAY['text_anchor'::text, 'canonical_fact'::text, 'state_change'::text, 'story_time'::text, 'story_relation'::text, 'planning_version'::text, 'rule'::text, 'observation'::text])) OR ((evidence_kind = ANY (ARRAY['card_field'::text, 'relation_field'::text])) AND (material_id IS NOT NULL) AND (field_key IS NOT NULL) AND (field_spec_hash IS NOT NULL) AND (observed_value_hash IS NOT NULL) AND (NOT is_unverified_observation) AND (num_nonnulls(text_anchor_id, fact_id, state_change_id, story_timing_id, story_relation_id, planning_version_id, rule_key, rule_version) = 0)))),
    CONSTRAINT quality_issue_evidence_material_kind_check CHECK ((material_kind = ANY (ARRAY['card'::text, 'relation'::text]))),
    CONSTRAINT world_evidence_exact_shape CHECK ((((evidence_kind = 'card_field'::text) AND (num_nonnulls(material_kind, material_id, card_version_id, field_key, field_spec_version_id, field_spec_hash, observed_value_hash) = 7) AND (material_kind = 'card'::text) AND (relation_version_id IS NULL) AND (field_spec_hash ~ '^[0-9a-f]{64}$'::text) AND (observed_value_hash ~ '^[0-9a-f]{64}$'::text)) OR ((evidence_kind = 'relation_field'::text) AND (num_nonnulls(material_kind, material_id, relation_version_id, field_key, field_spec_hash, observed_value_hash) = 6) AND (material_kind = 'relation'::text) AND (card_version_id IS NULL) AND (field_spec_version_id IS NULL) AND (field_spec_hash ~ '^[0-9a-f]{64}$'::text) AND (observed_value_hash ~ '^[0-9a-f]{64}$'::text)) OR ((evidence_kind <> ALL (ARRAY['card_field'::text, 'relation_field'::text])) AND (num_nonnulls(material_kind, material_id, card_version_id, relation_version_id, field_key, field_spec_version_id, field_spec_hash, observed_value_hash) = 0))))
);


