CREATE TABLE new_design.world_package_capability (
    contract text NOT NULL,
    operational boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT world_package_capability_contract_check CHECK ((contract = 'public_world_package_v1'::text))
);


--
-- Name: world_package_card_refs; Type: TABLE; Schema: new_design; Owner: -
--

CREATE TABLE new_design.world_package_card_refs (
    package_id uuid NOT NULL,
    source_card_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    type_version_id uuid NOT NULL,
    form_version_id uuid,
    section text NOT NULL,
    CONSTRAINT world_package_card_refs_section_check CHECK ((section = ANY (ARRAY['profile'::text, 'rules'::text, 'factions'::text, 'forces'::text, 'locations'::text, 'relations'::text])))
);


--
-- Name: world_package_field_baselines; Type: TABLE; Schema: new_design; Owner: -
--

CREATE TABLE new_design.world_package_field_baselines (
    command_id uuid NOT NULL,
    installation_id uuid NOT NULL,
    source_card_id uuid NOT NULL,
    source_key text NOT NULL,
    target_key text NOT NULL,
    public_version_id uuid NOT NULL,
    local_version_id uuid NOT NULL,
    public_value jsonb NOT NULL,
    local_value jsonb NOT NULL,
    CONSTRAINT world_package_field_baselines_local_value_check CHECK ((jsonb_typeof(local_value) = 'object'::text)),
    CONSTRAINT world_package_field_baselines_public_value_check CHECK ((jsonb_typeof(public_value) = 'object'::text))
);


