--
-- Name: world_package_installations; Type: TABLE; Schema: new_design; Owner: -
--

CREATE TABLE new_design.world_package_installations (
    id uuid NOT NULL,
    book_id uuid NOT NULL,
    package_id uuid NOT NULL,
    root_card_id uuid NOT NULL,
    sync_enabled boolean NOT NULL,
    origin text DEFAULT 'import'::text NOT NULL,
    request_key uuid NOT NULL,
    input_hash text NOT NULL,
    input jsonb NOT NULL,
    receipt jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT world_package_installations_input_check CHECK ((jsonb_typeof(input) = 'object'::text)),
    CONSTRAINT world_package_installations_input_hash_check CHECK ((input_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT world_package_installations_origin_check CHECK ((origin = ANY (ARRAY['import'::text, 'published_source'::text]))),
    CONSTRAINT world_package_installations_receipt_check CHECK ((jsonb_typeof(receipt) = 'object'::text))
);


