--
-- Name: world_package_versions; Type: TABLE; Schema: new_design; Owner: -
--

CREATE TABLE new_design.world_package_versions (
    id uuid NOT NULL,
    root_card_id uuid NOT NULL,
    root_version_id uuid NOT NULL,
    version integer NOT NULL,
    frame jsonb NOT NULL,
    frame_hash text NOT NULL,
    request_key uuid NOT NULL,
    input_hash text NOT NULL,
    input jsonb NOT NULL,
    receipt jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT world_package_versions_frame_check CHECK (((jsonb_typeof(frame) = 'object'::text) AND ((frame ->> 'contract'::text) = 'public_world_package_v1'::text))),
    CONSTRAINT world_package_versions_frame_hash_check CHECK ((frame_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT world_package_versions_input_check CHECK ((jsonb_typeof(input) = 'object'::text)),
    CONSTRAINT world_package_versions_input_hash_check CHECK ((input_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT world_package_versions_receipt_check CHECK ((jsonb_typeof(receipt) = 'object'::text)),
    CONSTRAINT world_package_versions_version_check CHECK ((version > 0))
);


